-- =============================================================
-- 00121_seed_e_shikaku.sql
-- E資格（JDLA Deep Learning for ENGINEER） Set A / 52問 / 5カテゴリ
-- シラバス2026（2026年8月試験E2026#2より適用・第1.0版）準拠。
-- G検定より数式・計算・仕組みの深さを要求される実装者向け資格のため、
-- calc(3段ロケット)とviz(SVG図解)を厚く使う。位置参照(A/B/C/D)は書かない。
-- 選択肢は長さ・密度を揃える（正解だけ長くしない）。
-- 本番の再現ではなく学習用オリジナル。
-- =============================================================

BEGIN;

-- ── subject ──
INSERT INTO public.subjects (slug, name, description, color, sort_order)
VALUES ('e-shikaku', 'E資格（JDLA Deep Learning for ENGINEER） Set A',
        'JDLA E資格 対策 第1弾。シラバス2026（2026年8月試験E2026#2より適用）準拠。本試験はCBT 120分・多肢選択式（4択中心）100問前後。G検定より数式・計算・仕組みの深さを要求される実装者向け資格。本番の再現ではなく学習用オリジナル。',
        '#C2255C', 180)
ON CONFLICT (slug) DO NOTHING;

-- ── categories（公式シラバスの大分類5個） ──
INSERT INTO public.categories (subject_id, name, color, sort_order)
SELECT s.id, v.name, v.color, v.sort_order
FROM public.subjects s
CROSS JOIN (VALUES
  ('1. 数学的基礎', '#58a6ff', 0),
  ('2. 機械学習', '#3fb950', 1),
  ('3. 深層学習の基礎', '#a371f7', 2),
  ('4. 深層学習の応用', '#f0883e', 3),
  ('5. 開発・運用環境', '#39c5cf', 4)
) AS v(name, color, sort_order)
WHERE s.slug = 'e-shikaku'
ON CONFLICT (subject_id, name) DO NOTHING;

-- ── questions ──
INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('e-shikaku-q1', '1. 数学的基礎', '2つの同じ形の行列AとBについて、通常の行列積ABとアダマール積A∘Bの違いとして正しいものはどれか。', NULL::text, '["行列積は行と列の内積で新しい行列を作る演算、アダマール積は同じ位置の要素同士を掛け合わせる演算で、結果の形も計算の意味も異なる。", "行列積とアダマール積は同じ形の行列同士であれば、呼び方が違うだけで計算の手順も結果も実際には一致する、単なる表記上の使い分けにすぎない。", "アダマール積は行列の行数と列数を入れ替えてから掛け算する演算である。", "行列積は要素ごとの掛け算、アダマール積は行と列の内積を取る演算である。"]', 0, '[0]', 'single', '{"asked": "行列積とアダマール積という2種類の「行列の掛け算」の違い。", "why_asked": "LSTMのゲート機構など、深層学習の随所でアダマール積(要素ごとの積)が使われるため、行列積と混同しないことが実装理解の土台になる。", "kid": "どちらも「掛け算」と呼ぶけど、やり方が全然違う2つの計算のこと。", "terms": [["アダマール積", "同じ位置の要素同士を掛け合わせる積。記号は∘。LSTMのゲート処理などで使われる"], ["内積", "2つのベクトルの対応する要素を掛けて全部足したもの。行列積の各要素はこの内積"]], "think": "行列積の(i,j)成分は「Aのi行目」と「Bのj列目」の内積。アダマール積の(i,j)成分は単純にA(i,j)×B(i,j)。形が同じでも計算のやり方も結果も違う。", "calc": "A = [[1,2],[3,4]]、B = [[5,6],[7,8]] とする\n行列積 AB の(1,1)成分 : 1×5 + 2×7 = 5+14 = 19\n行列積 AB の(1,2)成分 : 1×6 + 2×8 = 6+16 = 22\n→ AB = [[19,22],[43,50]]\nアダマール積 A∘B の(1,1)成分 : 1×5 = 5 ← 同じ位置同士を掛けるだけ\n→ A∘B = [[5,12],[21,32]]", "vs": "「行列同士の掛け算」と聞くとどちらも同じに聞こえるが、LSTMのゲート機構(忘却ゲート等)で使われるのはアダマール積(要素ごと)であり、全結合層の計算に使われるのは行列積(内積)。", "opt": ["正解。行列積は内積で新しい行列を作り、アダマール積は同じ位置の要素同士を掛け合わせる、別の演算である。", "計算方法が根本的に異なるため、AとBの中身によって結果は一般に一致しない。", "行と列を入れ替える操作は転置と呼ばれる別の演算であり、アダマール積の定義ではない。", "説明が入れ替わっている。要素ごとの掛け算はアダマール積、内積を取るのは行列積である。"]}'),
  ('e-shikaku-q2', '1. 数学的基礎', '行列Aを固有ベクトルvに作用させると、Av = λv のように「方向を変えずに長さだけλ倍する」ベクトルvと係数λが存在することがある。この関係の説明として正しいものはどれか。', NULL::text, '["vが固有ベクトル、λが固有値であり、Aを掛けてもvの向きは変わらず大きさだけがλ倍される。", "vが固有値、λが固有ベクトルであり、Aを掛けると向きも大きさも自由に変わる。", "固有値分解は行列を必ず2つの直交行列に分解する手法であり、固有ベクトルという概念そのものを一切使わずに計算できる方法だとされている。", "固有ベクトルはAを掛けると必ず0ベクトルになる特別な方向を指す。"]', 0, '[0]', 'single', '{"asked": "固有値・固有ベクトルという言葉の対応関係と意味。", "why_asked": "PCA(主成分分析)は共分散行列を固有値分解して「分散が最大の方向」を取り出す手法なので、固有値分解の意味を理解していないとPCAの仕組みが暗記になってしまう。", "kid": "ある行列を掛けても向きだけは変わらず、伸び縮みだけする特別な方向とその倍率のこと。", "terms": [["固有値(λ)", "行列を掛けたときにベクトルが伸び縮みする倍率"], ["主成分分析(PCA)", "データの分散共分散行列を固有値分解し、分散が最大の方向(固有ベクトル)を主成分として取り出す手法"]], "think": "PCAは「データが一番バラついている方向」を探す手法。データの共分散行列を固有値分解すると、固有値が大きい方向ほどデータの分散が大きい方向になる。固有値分解がPCAの計算エンジンになっている。", "calc": "対角行列 A = [[2,0],[0,3]] で確かめる\nベクトル v = (1,0) に A を掛ける\nAv = (2×1 + 0×0, 0×1 + 3×0) = (2, 0)\nこれは v = (1,0) を2倍しただけ → Av = 2v\n→ v=(1,0) は固有ベクトル、λ=2 が固有値\n同様に v=(0,1) は固有値3の固有ベクトルになる", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"18\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">固有ベクトルは向きを変えず長さだけ伸びる</text><line x1=\"40\" y1=\"110\" x2=\"300\" y2=\"110\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"70\" y1=\"120\" x2=\"70\" y2=\"20\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"70\" y1=\"110\" x2=\"150\" y2=\"70\" stroke=\"#8892a4\" stroke-width=\"2\" marker-end=\"url(#a1)\"/><text x=\"150\" y=\"64\" fill=\"#8892a4\" font-size=\"10\">v</text><line x1=\"70\" y1=\"110\" x2=\"230\" y2=\"30\" stroke=\"#3b82f6\" stroke-width=\"2.5\" marker-end=\"url(#a2)\"/><text x=\"238\" y=\"30\" fill=\"#60a5fa\" font-size=\"10\">Av = 2v</text><defs><marker id=\"a1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"4\" refY=\"4\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#8892a4\"/></marker><marker id=\"a2\" markerWidth=\"8\" markerHeight=\"8\" refX=\"4\" refY=\"4\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b82f6\"/></marker></defs><text x=\"170\" y=\"130\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">同じ直線上で長さだけ2倍になっている</text></svg>", "vs": "特異値分解(SVD)は正方行列でなくても使える一般化版。固有値分解は正方行列限定。", "opt": ["正解。vが向きを保ったまま伸び縮みする固有ベクトル、λがその倍率である固有値。", "固有値と固有ベクトルの呼び名が入れ替わっており、λはスカラー(倍率)であってベクトルではない。", "固有値分解は正方行列を固有ベクトル・固有値を使って分解する手法であり、固有ベクトルの概念そのものを使う。", "固有ベクトルは向きが保たれる特別な方向を指すのであって、必ず0ベクトルになるわけではない。"]}'),
  ('e-shikaku-q3', '1. 数学的基礎', 'カラー画像1枚を数値データとして表すとき、高さ・幅・チャネル(RGB)の3つの軸を持つ配列として扱うのが一般的である。このような多次元配列を指す語として最も適切なものはどれか。', NULL::text, '["テンソル。行列(2階)をさらに一般化した多次元配列で、画像は高さ・幅・チャネルの3階テンソルとして表せる。", "ベクトル。1つの軸しか持たない表現であり、高さ・幅・チャネルという3つの軸をまとめて1つの配列として表すことはそもそもできない。", "スカラー。1つの数値だけを表す概念であり、複数の軸を持つデータには使えない。", "行列。2つの軸しか持たないため、チャネル軸を含む画像には本来使えない表現である。"]', 0, '[0]', 'single', '{"asked": "複数の軸を持つ配列を指す一般的な呼び名。", "why_asked": "CNNの入出力の形(shape)を追うとき、「今何階のテンソルか」を意識できないと、ミニバッチ次元やチャネル次元の扱いで混乱しやすい。", "kid": "数字1個(スカラー)→並び(ベクトル)→表(行列)→もっと軸が増えたもの(テンソル)、という順番の一番広い呼び方。", "terms": [["階数(ランク)", "テンソルが持つ軸の数。行列は2階、画像1枚は3階"], ["アダマール積", "テンソル同士でも要素ごとの積として定義できる演算"]], "think": "スカラー(0階)→ベクトル(1階)→行列(2階)→テンソル(N階)という一般化の順番。画像1枚は高さ・幅・チャネルの3階テンソル、ミニバッチにすると枚数の軸が加わり4階テンソルになる。", "vs": "「行列のランク」という言葉は別の意味(独立な行/列の最大数)でも使われるので、テンソルの「階数」と混同しない。", "opt": ["正解。テンソルは行列をさらに一般化した多次元配列で、画像は3階テンソルとして扱える。", "ベクトルは1つの軸しか持たないため、高さ・幅・チャネルの3軸を同時に表すことはできない。", "スカラーは軸を持たない単一の数値であり、画像のような多軸データを表すことはできない。", "行列は2つの軸しか持たないため、チャネル軸まで含めた画像をそのまま表すには軸が1つ足りない。"]}'),
  ('e-shikaku-q4', '1. 数学的基礎', 'ある検査の陽性的中率を考えるとき、「検査結果が陽性という条件のもとで、実際に病気である確率」を表す量はどれか。', NULL::text, '["条件付き確率 P(病気|陽性)。ベイズの定理を使って事前確率と尤度から計算する。", "周辺確率 P(陽性)。病気の有無を無視して陽性になる確率全体を表すだけである。", "同時確率 P(病気, 陽性)。病気であり、かつ陽性である場合の割合を表すだけで、条件付けにはなっていない。", "尤度 P(陽性|病気)。病気だと分かっている前提で陽性になる確率であり、求めたい向きが逆になっている。"]', 0, '[0]', 'single', '{"asked": "「検査が陽性だったとき、本当に病気である確率」を表す確率の種類。", "why_asked": "ベイズの定理・ナイーブベイズ・MAP推定はどれも「結果から原因を逆算する」条件付き確率の計算が土台になる。", "kid": "「陽性が出た人たちの中で、本当に病気の人はどれくらいいる？」という割合のこと。", "terms": [["尤度", "ある原因(病気)を仮定したときに、そのデータ(陽性)が観測される確率"], ["事後確率", "データを見た後に更新された確率。ここではP(病気|陽性)"]], "think": "ベイズの定理は「原因→結果」の確率(尤度)から「結果→原因」の確率(事後確率)を逆算する道具。有病率が低いと、検査が陽性でも本当に病気である確率は意外と低くなる。", "calc": "母集団を1000人とする\n病気の人 : 1000人 × 1%(有病率) = 10人\n健康な人 : 1000人 - 10人 = 990人\n病気で陽性になる人(感度80%) : 10人 × 0.8 = 8人\n健康なのに陽性になる人(偽陽性率10%) : 990人 × 0.1 = 99人\n陽性になった人の合計 : 8人 + 99人 = 107人\n陽性のうち本当に病気の割合 : 8人 ÷ 107人 ≈ 7.5%\n← これがP(病気|陽性)。検査が陽性でも本当に病気の確率は1割未満というベイズの罠", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">1000人のうち「陽性」107人の内訳</text><rect x=\"30\" y=\"35\" width=\"280\" height=\"34\" fill=\"#2a2f3f\" stroke=\"#2a2f3f\"/><rect x=\"30\" y=\"35\" width=\"8.5\" height=\"34\" fill=\"#c47070\"/><text x=\"46\" y=\"56\" fill=\"#e8eaf0\" font-size=\"10\">病気で陽性 8人</text><rect x=\"30\" y=\"80\" width=\"280\" height=\"34\" fill=\"#2a2f3f\" stroke=\"#2a2f3f\"/><rect x=\"30\" y=\"80\" width=\"104\" height=\"34\" fill=\"#c9a04a\"/><text x=\"46\" y=\"101\" fill=\"#141720\" font-size=\"10\">健康なのに陽性 99人</text><text x=\"170\" y=\"130\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">陽性107人のうち本当に病気は8人だけ ≈ 7.5%</text></svg>", "vs": "「陽性」という結果だけを見た確率(周辺確率)と、「陽性という条件のもとで病気である」確率(条件付き確率)は別物。位置参照ではなく中身で区別する。", "opt": ["正解。求めたいのは「陽性という条件のもとでの病気の確率」であり、これは条件付き確率でベイズの定理を使って求める。", "周辺確率P(陽性)は病気かどうかを無視した「とにかく陽性になる確率」であり、病気かどうかの情報が抜け落ちている。", "同時確率は「病気かつ陽性」の割合であって、陽性という条件のもとでの割合(分母をP(陽性)にする条件付き確率)にはなっていない。", "尤度P(陽性|病気)は逆向きの確率で、これ単体では「陽性のときに本当に病気か」は分からない。"]}'),
  ('e-shikaku-q5', '1. 数学的基礎', 'サイコロを1回振ったときの出目Xについて、期待値E[X]と分散V[X]の求め方の説明として正しいものはどれか。', NULL::text, '["期待値は各出目に確率を掛けて全部足した値、分散は出目が期待値からどれだけばらつくかを2乗の平均で測った値。", "期待値は出目の中でいちばんよく出る最頻値、分散は出目の最大値と最小値の差である範囲(レンジ)を表す量である。", "期待値は出目の中央値、分散は出目を全部掛け合わせた値である。", "期待値と分散はどちらも同じ計算式で、出目を単純に平均しただけの値である。"]', 0, '[0]', 'single', '{"asked": "確率変数の期待値と分散という2つの基本統計量の求め方。", "why_asked": "損失関数の期待値、方策勾配法の期待報酬など、深層学習・強化学習の理論はほぼ全て期待値の式の上に組み立てられている。", "kid": "期待値は「だいたいこのくらいの値になる」という重心、分散は「その周りにどれだけ散らばるか」という目安。", "terms": [["期待値E[X]", "確率の重みつき平均。「平均するとだいたいこの値になる」という中心の目安"], ["分散V[X]", "出目が期待値からどれだけ散らばっているかを2乗で測った量"]], "think": "期待値は「重心」、分散は「散らばり具合」。分散はE[X^2]-(E[X])^2という近道の公式で求められる。", "calc": "サイコロの出目は1〜6、確率はどれも1/6\n期待値 E[X] = (1+2+3+4+5+6) ÷ 6 = 21 ÷ 6 = 3.5\nE[X^2] = (1²+2²+3²+4²+5²+6²) ÷ 6 = (1+4+9+16+25+36) ÷ 6 = 91 ÷ 6 ≈ 15.17\n分散 V[X] = E[X^2] - (E[X])² = 15.17 - 3.5² = 15.17 - 12.25 = 2.92", "vs": "標準偏差は分散の平方根で、単位を元のデータ(出目そのもの)に戻したもの。", "opt": ["正解。期待値は確率で重み付けした平均、分散は期待値からのズレを2乗して平均した散らばりの指標。", "最頻値・範囲(最大-最小)は別の統計量であり、期待値・分散の定義とは異なる。", "中央値・単純な掛け算は期待値・分散の定義ではなく、確率による重み付けが反映されていない。", "期待値は確率で重み付けした平均、分散はそこからのズレの2乗の平均であり、単純な平均1本では両方を表せない。"]}'),
  ('e-shikaku-q6', '1. 数学的基礎', 'パラメータθを推定する方法として、「観測データが最も起こりやすくなるθ」を選ぶ最尤推定(MLE)と、「データに加えてθ自体の事前知識も考慮して選ぶ」MAP推定がある。この2つの違いとして正しいものはどれか。', NULL::text, '["MLEは尤度P(データ|θ)だけを最大化するのに対し、MAP推定は尤度に事前分布P(θ)を掛けた事後確率を最大化する。", "MLEは事前分布を使い、MAP推定は尤度だけを使う、という逆の関係である。", "MLEとMAP推定はどちらも尤度と事前分布の両方を必ず使う推定方法であり、事前分布の形によらず計算結果は常に完全に一致する。", "MLEはベイズ推定の別名であり、MAP推定は頻度主義の推定法である。"]', 0, '[0]', 'single', '{"asked": "最尤推定(MLE)とMAP推定という2つのパラメータ推定方法の違い。", "why_asked": "正則化(L2正則化)は「重みに正規分布の事前分布を仮定したMAP推定」として解釈できるなど、最適化の理論的な背景を理解する土台になる。", "kid": "MLEは「データだけを見て一番それらしいθ」を選び、MAP推定は「データ＋あらかじめの予想」も加味してθを選ぶ。", "terms": [["事前分布P(θ)", "データを見る前に持っているθについての知識・仮定"], ["事後確率P(θ|データ)", "データを見た後に更新されたθの確からしさ"]], "think": "MAP推定はargmax P(θ|データ) = argmax P(データ|θ)P(θ) と書ける。事前分布P(θ)が一様(何の予想も無い)なら、MAP推定はMLEと一致する。MAPはMLEに「事前知識」という重みを足したものと言える。", "vs": "ベイズ推定はθの分布全体を求めるのに対し、MAP推定はその分布の頂点(最頻値)1点だけを答えとして選ぶ、という点でも違う。", "opt": ["正解。MLEは尤度のみ最大化、MAP推定は尤度×事前分布(事後確率)を最大化する。", "説明が入れ替わっている。事前分布を使うのはMAP推定であり、MLEは事前分布を使わない。", "事前分布が一様でない限り、MLEとMAP推定は一般に異なる結果を与える。", "MLEもMAP推定も、事前分布の扱い方が違うだけでどちらもベイズ流・頻度流という単純な二分では説明しきれない。"]}'),
  ('e-shikaku-q7', '1. 数学的基礎', 'あるコインを投げたときの結果(表・裏)が生み出す情報量の平均を表す指標として、シャノンのエントロピーH = -Σp_i log2(p_i) がある。表も裏も確率1/2の公正なコインのエントロピーを求めるとどうなるか。', NULL::text, '["1ビット。最も予測しづらい(不確実性が最大の)状態であり、公正なコインのエントロピーはちょうど1になる。", "0ビット。表か裏のどちらかが必ず出るという結果が完全に予測できる状態のときにとる値であり、五分五分の公正なコインには当てはまらない。", "2ビット。出目の数を単純にビット数として使ってしまっている。", "0.5ビット。確率1/2をそのままビット数として使ってしまっている。"]', 0, '[0]', 'single', '{"asked": "確率1/2・1/2の公正なコインのシャノンエントロピー。", "why_asked": "クロスエントロピー誤差・KLダイバージェンスはどれもこのエントロピーの考え方の上に定義されており、先にエントロピー単体の意味を押さえておくと後続の損失関数が腹落ちする。", "kid": "「次に表か裏か、どれだけ予想しづらいか」を数字にしたもの。五分五分が一番予想しづらい。", "terms": [["エントロピー(H)", "確率分布の「予測しにくさ」を測る量。均等に散らばっているほど大きい"], ["ビット", "情報量の単位。log2を使うときの単位"]], "think": "確率が偏っている(例えば表99%)ほど結果は予測しやすく、エントロピーは0に近づく。確率が半々のときが最も予測しづらく、エントロピーは最大になる。", "calc": "H = -(1/2 × log2(1/2) + 1/2 × log2(1/2))\nlog2(1/2) = -1 ← 「1/2は2の-1乗」という意味\n各項 : 1/2 × (-1) = -0.5\n2つ足す : -0.5 + (-0.5) = -1\nマイナスを掛けて符号を反転 : -(-1) = 1\n→ H = 1ビット", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">H(p)は p=0.5 のとき最大になる</text><line x1=\"40\" y1=\"112\" x2=\"310\" y2=\"112\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"40\" y1=\"112\" x2=\"40\" y2=\"35\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><path d=\"M 40,112 Q 175,38 310,112\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"2.5\"/><circle cx=\"175\" cy=\"50\" r=\"3.5\" fill=\"#60a5fa\"/><text x=\"228\" y=\"53\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\">1ビット(最大)</text><circle cx=\"40\" cy=\"112\" r=\"3\" fill=\"#8892a4\"/><circle cx=\"310\" cy=\"112\" r=\"3\" fill=\"#8892a4\"/><text x=\"40\" y=\"126\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">p=0</text><text x=\"175\" y=\"126\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">p=0.5</text><text x=\"310\" y=\"126\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">p=1</text><text x=\"22\" y=\"116\" fill=\"#8892a4\" font-size=\"9\">0</text></svg>", "vs": "クロスエントロピーは「本当の分布」と「予測した分布」という2つの分布のズレを測る指標で、エントロピー単体(1つの分布の不確実性)とは別物。", "opt": ["正解。公正なコインは最も予測しづらい状態であり、エントロピーは最大値の1ビットになる。", "0ビットは結果が完全に予測できる(確率が0か1に偏っている)ときの値で、五分五分のコインには当てはまらない。", "出目の数(2)をそのままビット数として使う考え方ではなく、確率を使って計算する必要がある。", "確率の値をそのままビット数として使うのではなく、log2を使った式で計算する必要がある。"]}'),
  ('e-shikaku-q8', '1. 数学的基礎', '3クラス分類で、正解ラベルがone-hotベクトル[0, 1, 0](2番目のクラスが正解)、モデルのsoftmax出力が[0.2, 0.5, 0.3]だったとき、クロスエントロピー誤差 L = -Σy_i log(p_i) の値はどうなるか。', NULL::text, '["-log(0.5) ≈ 0.69。正解クラスに対応する確率だけが式に残り、それ以外のクラスの予測値は式から消える。", "-log(0.2) - log(0.5) - log(0.3) の3項をすべて足した値。正解でないクラスの項もそのまま残ってしまっている。", "0.5そのもの。正解クラスの予測確率をそのまま誤差として使ってしまっている。", "1 - 0.5 = 0.5。正解確率との差を単純に引き算しただけの値になってしまっている。"]', 0, '[0]', 'single', '{"asked": "one-hotラベルとsoftmax出力からクロスエントロピー誤差を計算する手順。", "why_asked": "多クラス分類の出力層(ソフトマックス)と損失関数(クロスエントロピー)の組み合わせは深層学習で最も頻出する形なので、数値で追える理解が求められる。", "kid": "正解のクラスに、モデルがどれだけ自信を持って正解できていたかを数値にしたもの。自信が高いほど誤差は小さくなる。", "terms": [["one-hotベクトル", "正解のクラスだけ1、それ以外は0で表したベクトル"], ["softmax関数", "出力をすべて0〜1の確率に変換し、合計が1になるようにする関数"]], "think": "y_iが0のクラスはΣの中で必ず0倍されて消えるので、実質「正解クラスの予測確率だけ」を見る式になる。予測確率が1に近いほど-log(p)は0に近づき、誤差が小さくなる。", "calc": "正解ラベル(one-hot) : [0, 1, 0]\n予測確率(softmax出力) : [0.2, 0.5, 0.3]\nL = -(0×log(0.2) + 1×log(0.5) + 0×log(0.3))\n← y_iが0の項は掛け算で消える\nL = -log(0.5)\nlog(0.5) ≈ -0.69 ← 自然対数で「0.5はeの-0.69乗」という意味\nL = -(-0.69) = 0.69", "vs": "2値分類のバイナリクロスエントロピーは正解・不正解の2項が両方残る式になる点がここと違う。", "opt": ["正解。one-hotで0になっているクラスの項は消え、正解クラスの予測確率だけが-log()の中に残る。", "正解ラベルが0のクラスの項はy_iの掛け算で0になって消えるため、3項すべてを残すのは誤り。", "予測確率をそのまま誤差として使うのではなく、-log()を通した値がクロスエントロピー誤差になる。", "1から引く操作はクロスエントロピー誤差の定義には含まれておらず、-log(p_k)を計算する必要がある。"]}'),
  ('e-shikaku-q9', '2. 機械学習', '新しいデータ点のクラスを、周囲にある「距離が近い」既知のデータ点k個の多数決で決める手法はどれか。', NULL::text, '["k近傍法(k-NN)。教師あり学習で、学習時にはモデルを作らず、予測時に近いk個を探して多数決する。", "k-means法。教師なし学習で、データをk個のグループに分けるクラスタリング手法であり、ラベルの多数決は行わない。", "主成分分析(PCA)。次元を圧縮する手法であり、距離やラベルの多数決とは関係ない。", "サポートベクターマシン。マージンを最大化する境界線を学習する手法であり、予測時に近傍点を探す方式ではない。"]', 0, '[0]', 'single', '{"asked": "近いデータ点k個の多数決でクラスを決める手法の名前。", "why_asked": "k-NNとk-meansは名前が似ているため、教師あり/教師なしの取り違えが定番の失点ポイントになる。", "kid": "新しいデータの近くにいる「先輩データ」たちに、多数決でクラスを教えてもらう手法。", "terms": [["k", "多数決に使う近傍点の個数。ハイパーパラメータとして事前に決める"], ["距離計算", "近さを測るものさし。ユークリッド距離やマンハッタン距離などがある"]], "think": "k-NNは「学習」のフェーズが実質無く(怠惰学習)、予測のたびに全データとの距離を測って一番近いk個を探す。kを大きくすると境界が滑らかに、小さくすると複雑になる。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">近い3点(k=3)の多数決でクラスを決める</text><circle cx=\"90\" cy=\"50\" r=\"4\" fill=\"#6ab08d\"/><circle cx=\"120\" cy=\"75\" r=\"4\" fill=\"#6ab08d\"/><circle cx=\"140\" cy=\"45\" r=\"4\" fill=\"#6ab08d\"/><text x=\"80\" y=\"35\" fill=\"#6ab08d\" font-size=\"9\">緑クラス</text><circle cx=\"235\" cy=\"95\" r=\"4\" fill=\"#c47070\"/><circle cx=\"258\" cy=\"58\" r=\"4\" fill=\"#c47070\"/><circle cx=\"272\" cy=\"98\" r=\"4\" fill=\"#c47070\"/><text x=\"260\" y=\"42\" fill=\"#c47070\" font-size=\"9\">赤クラス</text><circle cx=\"150\" cy=\"68\" r=\"6\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"2\"/><text x=\"150\" y=\"98\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">新規点</text><circle cx=\"150\" cy=\"68\" r=\"48\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><text x=\"170\" y=\"130\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">円内の3点は緑2:赤1 → 新規点は緑と判定</text></svg>", "vs": "k-meansと名前が似ているが、k-NNは教師あり(ラベルを使う)・k-meansは教師なし(ラベルを使わない)で全くの別物(頻出の引っかけ)。", "opt": ["正解。k近傍法は教師あり学習で、予測時に近いk個のラベルの多数決でクラスを決める。", "k-meansはラベルを使わない教師なしのクラスタリング手法であり、既知ラベルの多数決という説明は当てはまらない。", "PCAは次元圧縮の手法であり、距離に基づく多数決でクラスを決める仕組みは持たない。", "SVMはマージンを最大化する境界線を学習する手法で、k-NNのように予測のたびに近傍点を探す方式ではない。"]}'),
  ('e-shikaku-q10', '2. 機械学習', '2点A(1, 2)とB(4, 6)の間のユークリッド距離とマンハッタン距離をそれぞれ求めるとどうなるか。', NULL::text, '["ユークリッド距離は5、マンハッタン距離は7。ユークリッドは差を2乗して足してから平方根、マンハッタンは差の絶対値をそのまま足す。", "ユークリッド距離は7、マンハッタン距離は5。2つの計算方法が入れ替わってしまっている。", "ユークリッド距離もマンハッタン距離も同じ7になる。2つの距離は本来計算方法が違うが、この座標の組み合わせではどちらの式でも同じ値になってしまう。", "ユークリッド距離は25、マンハッタン距離は7。2乗した値をそのまま距離として使ってしまっている。"]', 0, '[0]', 'single', '{"asked": "2点間のユークリッド距離とマンハッタン距離の計算。", "why_asked": "k-NNやクラスタリングの「近さ」の定義そのものであり、距離の種類によって同じデータでも近傍の判定結果が変わりうる。", "kid": "ユークリッド距離は「まっすぐ測った距離」、マンハッタン距離は「碁盤の目の道を歩いた距離」。", "terms": [["ユークリッド距離", "直線でまっすぐ測った距離。差を2乗して足して平方根を取る"], ["マンハッタン距離", "碁盤の目状の道を移動する距離。座標軸に沿った移動距離の合計"]], "think": "ユークリッドは「まっすぐな最短距離」、マンハッタンは「碁盤の目の街を移動する距離」というイメージの違いが、そのまま計算式の違いになる。", "calc": "x座標の差 : 4 - 1 = 3\ny座標の差 : 6 - 2 = 4\nユークリッド距離 : √(3² + 4²) = √(9+16) = √25 = 5\nマンハッタン距離 : |3| + |4| = 3 + 4 = 7", "vs": "コサイン距離は「向き」の近さを見る指標で、大きさ(長さ)を無視する点がこの2つと違う。", "opt": ["正解。ユークリッド距離は2乗和の平方根で5、マンハッタン距離は絶対値の和で7になる。", "2つの距離の計算方法が入れ替わっており、平方根を使う方がユークリッド距離、使わない方がマンハッタン距離である。", "計算方法が異なるため、この例では5と7という異なる値になり、一致しない。", "2乗した値の合計(25)をそのまま距離として使うのではなく、平方根を取る必要がある。"]}'),
  ('e-shikaku-q11', '2. 機械学習', '線形回帰の損失関数に正則化項を加える手法のうち、Lasso回帰(L1正則化)がRidge回帰(L2正則化)と比べて持つ特徴として正しいものはどれか。', NULL::text, '["一部の係数をちょうど0にできるため、不要な特徴量を自動的に取り除く「特徴量選択」の効果を持つ。", "すべての係数を0に近づけるが、ちょうど0にはならず、特徴量選択の効果は持たない。", "正則化項を使わない通常の線形回帰と全く同じ結果になるため、追加のペナルティを課しても過学習を抑える効果そのものを持たない。", "係数の大きさに関係なく、常に全ての特徴量を均等に使うよう強制する効果を持つ。"]', 0, '[0]', 'single', '{"asked": "L1正則化(Lasso)がL2正則化(Ridge)と比べて持つ特有の効果。", "why_asked": "正則化項の効き方の違い(疎になるかどうか)は、特徴量選択・多重共線性対策の実務判断に直結するため頻出。", "kid": "Lassoは「使わない特徴量をきっぱりゼロにする」、Ridgeは「全部の特徴量を少しずつ弱める」という違い。", "terms": [["L1正則化(Lasso)", "係数の絶対値の合計をペナルティにする。スパース(疎)な解になりやすい"], ["L2正則化(Ridge)", "係数の2乗の合計をペナルティにする。全体を均等に縮小する"]], "think": "L1正則化(絶対値の和)はグラフの形が尖っているため、最適化の過程で係数がちょうど0で止まりやすい。L2正則化(2乗の和)はなめらかな形なので、係数は小さくなるが0ぴったりにはなりにくい。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"85\" y=\"16\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">L1(ひし形)</text><text x=\"255\" y=\"16\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">L2(円)</text><polygon points=\"85,30 115,70 85,110 55,70\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"2\"/><circle cx=\"85\" cy=\"110\" r=\"4\" fill=\"#6ab08d\"/><text x=\"85\" y=\"128\" fill=\"#6ab08d\" font-size=\"9\" text-anchor=\"middle\">頂点(軸上)で接する→0になる</text><circle cx=\"255\" cy=\"70\" r=\"40\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"2\"/><circle cx=\"283\" cy=\"53\" r=\"4\" fill=\"#c9a04a\"/><text x=\"255\" y=\"128\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\">軸から外れた点で接する</text></svg>", "vs": "多重共線性(似た特徴量同士が強く相関する状態)が強いとき、Ridgeは係数を分散させて安定させるが、Lassoはどちらか一方だけを残して不安定になりやすい。", "opt": ["正解。L1正則化は損失を最小化する過程で係数がちょうど0になりやすく、特徴量選択の効果を持つ。", "係数を0に近づけるが0ぴったりにはなりにくいのはL2正則化(Ridge)の特徴であり、L1正則化の説明としては逆である。", "正則化項を加えることで大きすぎる係数にペナルティが掛かるため、通常の線形回帰と結果が変わり過学習が抑えられる。", "正則化は不要な特徴量の影響を抑える方向に働くのであって、全特徴量を均等に使うことを強制するものではない。"]}'),
  ('e-shikaku-q12', '2. 機械学習', 'モデルの予測誤差を「バイアス」と「バリアンス」に分解して考えるとき、単純すぎるモデル(例:直線であらゆるデータを近似する)で起きやすい問題として正しいものはどれか。', NULL::text, '["バイアスが大きく過少適合(underfitting)になりやすい。モデルの表現力が足りず、訓練データすら十分に当てはめられない。", "バリアンスが大きく過剰適合(overfitting)になりやすい。モデルの表現力が高すぎて、訓練データに含まれる細かいノイズまで丸ごと覚えてしまう。", "バイアスもバリアンスも常に0になり、誤差が発生しなくなる。", "バリアンスが大きく、訓練データに対する誤差だけが極端に小さくなる。"]', 0, '[0]', 'single', '{"asked": "モデルが単純すぎるときに起きやすい、バイアス・バリアンスどちら寄りの問題か。", "why_asked": "モデル選択・ハイパーパラメータ調整の判断基準そのもの(訓練誤差と検証誤差のどちらが問題かを見て、複雑さを増減する)になる。", "kid": "簡単すぎるモデルは「そもそも当てはまらない」タイプの誤差が大きくなる。", "terms": [["バイアス", "モデルの表現力不足による、体系的なズレ"], ["バリアンス", "訓練データが変わるたびに予測が大きくぶれる度合い"]], "think": "モデルが単純すぎる→表現力不足で「そもそも当てはまらない」(バイアス大)。モデルが複雑すぎる→訓練データのクセまで覚えて「新しいデータに弱い」(バリアンス大)。ちょうど良い複雑さを探すのがモデル選択。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">モデルの複雑さと誤差の関係</text><line x1=\"35\" y1=\"122\" x2=\"310\" y2=\"122\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><path d=\"M 35,42 C 120,95 160,110 310,119\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"2\"/><text x=\"55\" y=\"36\" fill=\"#c47070\" font-size=\"9\">バイアス</text><path d=\"M 35,119 C 160,110 200,95 310,42\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"2\"/><text x=\"270\" y=\"36\" fill=\"#c9a04a\" font-size=\"9\">バリアンス</text><path d=\"M 35,68 C 130,32 210,32 310,68\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"2.5\" stroke-dasharray=\"4,3\"/><text x=\"170\" y=\"58\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">合計誤差(U字)</text><text x=\"55\" y=\"136\" fill=\"#8892a4\" font-size=\"9\">単純(過少適合)</text><text x=\"245\" y=\"136\" fill=\"#8892a4\" font-size=\"9\">複雑(過学習)</text></svg>", "vs": "過学習(バリアンス大)と過少適合(バイアス大)は逆方向の失敗であり、どちらもモデルの複雑さの調整不足が原因。", "opt": ["正解。単純すぎるモデルは表現力不足でバイアスが大きくなり、訓練データにすら十分当てはまらない過少適合になりやすい。", "バリアンスが大きく過剰適合になりやすいのは、単純すぎるモデルではなく複雑すぎるモデルの特徴である。", "モデルを単純にしてもバイアス・バリアンスが両方0になることはなく、バイアスが増える方向に働く。", "訓練誤差だけが極端に小さくなるのは複雑すぎるモデル(過学習)の症状であり、単純すぎるモデルでは訓練誤差自体が下がりにくい。"]}'),
  ('e-shikaku-q13', '2. 機械学習', 'ロジスティック回帰で線形結合の出力(ロジット)がz=0だったとき、シグモイド関数σ(z)=1/(1+e^{-z})を通した後の確率はどうなるか。', NULL::text, '["0.5。z=0はe^0=1になるため、1/(1+1)=0.5となり、境界線上(五分五分)を表す。", "0。ロジットzがちょうど0になると、シグモイド関数の出力もそのまま0まで下がってしまうという計算になっている。", "1。zが0のときシグモイドの出力がそのまま1になってしまっている。", "無限大。分母が0になって計算できなくなってしまっている。"]', 0, '[0]', 'single', '{"asked": "ロジット(線形結合の出力)が0のときのシグモイド関数の値。", "why_asked": "ロジスティック回帰の判定境界(0.5)がどこから来るかを数式レベルで理解しているかを問う定番の計算。", "kid": "ロジットがちょうど真ん中(0)のとき、確率もちょうど真ん中(0.5)になるという話。", "terms": [["ロジット(z)", "線形結合の生の出力。-∞〜+∞の範囲を取りうる"], ["シグモイド関数", "ロジットを0〜1の確率に押し込める、S字カーブの変換"]], "think": "zが大きいほどσ(z)は1に近づき、zが小さい(負に大きい)ほど0に近づく。z=0はちょうど真ん中で確率0.5になり、これが分類の境界線になる。", "calc": "z = 0\ne^{-z} = e^0 = 1 ← 「何かの0乗は1」\nσ(z) = 1 ÷ (1 + 1) = 1 ÷ 2 = 0.5", "vs": "名前に「回帰」と付くが、ロジスティック回帰は分類手法である。ソフトマックス関数はこれを多クラスに一般化したもの。", "opt": ["正解。z=0のときe^{-z}=1となり、σ(0)=1/(1+1)=0.5になる。", "z=0でシグモイドの出力が0になるのではなく、分母が1+1=2になるためσ(0)=0.5である。", "z=0でシグモイドの出力が1になるのではなく、σ(0)=0.5である。1に近づくのはzが大きく正のときである。", "分母が1+e^{-z}=1+1=2となり0にはならないため、無限大になることはない。"]}'),
  ('e-shikaku-q14', '2. 機械学習', 'サポートベクターマシン(SVM)が2クラスを分ける境界線を引くときに最大化しようとしているものはどれか。', NULL::text, '["マージン。境界線から両クラスの最も近いデータ点(サポートベクター)までの距離を、できるだけ大きく取ろうとする。", "訓練データ全体の正解率。境界線をどこに引くかという幾何学的な余白は考えず、正解率という指標だけを直接最大化しようとする。", "クラス間の重心の距離。両クラスの平均位置同士の距離だけを見て境界線を決めようとする。", "境界線の傾きの絶対値。境界線をできるだけ急な角度にしようとする。"]', 0, '[0]', 'single', '{"asked": "SVMが境界線を引くときに最大化しようとしている量。", "why_asked": "マージン最大化という発想はSVM特有の目的関数であり、ロジスティック回帰など他の分類手法との設計思想の違いを問う定番。", "kid": "境界線と、境界線に一番近いデータとの間の「余白」をできるだけ広く取ろうとする。", "terms": [["サポートベクター", "境界線に最も近く、マージンの大きさを決めているデータ点"], ["カーネル法", "直線で分けられないデータを、高次元空間に写して分けやすくするテクニック"]], "think": "境界線ぎりぎりにデータがあると、新しいデータが少しズレただけで誤分類しやすい。SVMは境界線から一番近いデータ(サポートベクター)までの余白=マージンを最大にすることで、未知のデータにも強い境界線を選ぶ。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">境界線とマージン(余白)</text><circle cx=\"70\" cy=\"40\" r=\"4\" fill=\"#6ab08d\"/><circle cx=\"100\" cy=\"60\" r=\"4\" fill=\"#6ab08d\"/><circle cx=\"60\" cy=\"80\" r=\"4\" fill=\"#6ab08d\"/><circle cx=\"120\" cy=\"95\" r=\"4\" fill=\"#6ab08d\" stroke=\"#e8eaf0\" stroke-width=\"1.5\"/><circle cx=\"260\" cy=\"45\" r=\"4\" fill=\"#c47070\"/><circle cx=\"230\" cy=\"65\" r=\"4\" fill=\"#c47070\"/><circle cx=\"270\" cy=\"90\" r=\"4\" fill=\"#c47070\"/><circle cx=\"200\" cy=\"55\" r=\"4\" fill=\"#c47070\" stroke=\"#e8eaf0\" stroke-width=\"1.5\"/><line x1=\"150\" y1=\"20\" x2=\"200\" y2=\"120\" stroke=\"#3b82f6\" stroke-width=\"2.5\"/><line x1=\"120\" y1=\"20\" x2=\"170\" y2=\"120\" stroke=\"#8892a4\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><line x1=\"180\" y1=\"20\" x2=\"230\" y2=\"120\" stroke=\"#8892a4\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><text x=\"170\" y=\"135\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">丸で囲まれた点がサポートベクター。破線の幅=マージン</text></svg>", "vs": "ハードマージンは誤分類を一切許さない厳格な設定、ソフトマージンは多少のはみ出しを許容して汎化性能を上げる設定。", "opt": ["正解。SVMは境界線からサポートベクターまでの距離(マージン)を最大化するように学習する。", "正解率だけを直接最大化する目的関数ではなく、マージンという幾何学的な量を最大化する点がSVMの特徴である。", "クラスの重心同士の距離ではなく、境界線に最も近い個々のデータ点(サポートベクター)との距離を見ている。", "境界線の傾きの大きさそのものを最大化する目的関数ではない。"]}'),
  ('e-shikaku-q15', '2. 機械学習', 'あるノードにクラスA(6件)とクラスB(4件)、合計10件が混ざっているとき、Gini係数(不純度) G = 1 - Σp_i² で求めるとどうなるか。', NULL::text, '["0.48。クラスAの割合0.6とクラスBの割合0.4をそれぞれ2乗して足し、1から引く。", "0.6。クラスAの割合をそのまま、2乗も1からの引き算もせずにGini係数の値として使ってしまっている。", "1.0。2つのクラスが混ざっている状態を、最大の不純度として扱ってしまっている。", "0.24。2つの割合をそのまま掛け算しただけで、2乗と1からの引き算を行っていない。"]', 0, '[0]', 'single', '{"asked": "2クラスが6:4で混ざったノードのGini係数の計算。", "why_asked": "決定木はこのGini係数(またはエントロピー)が下がる分岐を選んで育つため、木がどう分岐を選んでいるかを理解する土台になる。", "kid": "1つの箱にどれだけ違う種類のものが混ざっているかを数字にしたもの。混ざっているほど大きい値になる。", "terms": [["Gini係数(不純度)", "1つのノードにどれだけ複数クラスが混ざっているかを表す値。0なら完全に単一クラス"], ["分類木", "Gini係数などを使って、不純度が下がるようにデータを分岐させていく決定木"]], "think": "Gini係数は「ランダムに2つ選んだときにクラスが違う確率」に近いイメージ。1種類しかないノード(純粋)ならG=0、半々に混ざっているとGが最大になる。決定木はこのGiniが下がる分岐を選んで育つ。", "calc": "クラスAの割合 : 6 ÷ 10 = 0.6\nクラスBの割合 : 4 ÷ 10 = 0.4\nそれぞれ2乗 : 0.6² = 0.36 、 0.4² = 0.16\n2乗の合計 : 0.36 + 0.16 = 0.52\nG = 1 - 0.52 = 0.48", "vs": "Random Forestは複数の決定木をバギング(並列・多数決)でまとめる手法、勾配ブースティングは決定木を逐次的に誤りを補正しながら足していく手法で、両者は「並列か逐次か」が逆。", "opt": ["正解。各クラスの割合を2乗して足し、1から引くとG=1-0.52=0.48になる。", "クラスAの割合(0.6)をそのままGini係数として使うのではなく、2乗和を1から引く計算が必要になる。", "2つのクラスが混ざっている状態はGiniが大きくなる方向ではあるが、最大値の1にはならず、この例では0.48になる。", "2つの割合をそのまま掛け算(0.6×0.4=0.24)するのではなく、それぞれ2乗してから足し合わせて1から引く必要がある。"]}'),
  ('e-shikaku-q16', '2. 機械学習', 'あるデータをPCAで分解したところ、各主成分の分散が[12, 6, 2](合計20)だった。第一主成分の寄与率はどうなるか。', NULL::text, '["60%。第一主成分の分散12を、全主成分の分散の合計20で割った値。", "12%。分散の値をそのままパーセントとして使ってしまっている。", "20%。合計の分散をそのままパーセントとして使ってしまっている。", "40%。第一主成分以外の分散(6+2=8)の割合を求めてしまっている。"]', 0, '[0]', 'single', '{"asked": "各主成分の分散から、第一主成分の寄与率を求める計算。", "why_asked": "次元削減でいくつの主成分を残すかを決める実務判断は、この寄与率(や累積寄与率)を根拠にすることが多い。", "kid": "その主成分が、データ全体のバラつきのうち何%を説明できているかという割合。", "terms": [["寄与率", "その主成分がデータ全体の分散(バラつき)のうち何%を説明しているかを表す割合"], ["累積寄与率", "上位いくつかの主成分の寄与率を足し合わせた値。次元削減後にどれだけ情報を残せたかの目安"]], "think": "PCAは分散が大きい方向から順に第一主成分、第二主成分…と並べる。寄与率が高い主成分だけ残せば、情報をあまり失わずに次元を減らせる。", "calc": "全主成分の分散の合計 : 12 + 6 + 2 = 20\n第一主成分の寄与率 : 12 ÷ 20 = 0.6\nパーセントに直す : 0.6 × 100 = 60%", "vs": "t-SNEも次元削減の一種だが、寄与率のような線形な指標では説明できない非線形な圧縮方法で、可視化目的で使われることが多い。", "opt": ["正解。第一主成分の分散12を全体の分散の合計20で割ると0.6、パーセントにすると60%になる。", "分散の値(12)をそのままパーセントとして使うのではなく、全体の合計で割る必要がある。", "合計の分散(20)ではなく、第一主成分自身の分散(12)を合計で割った値が寄与率になる。", "第一主成分「以外」の割合ではなく、第一主成分「自身」の割合(12/20=60%)を求める必要がある。"]}'),
  ('e-shikaku-q17', '2. 機械学習', '教師なし学習のクラスタリング手法のうち、k-means法と階層的クラスタリングの違いとして正しいものはどれか。', NULL::text, '["k-meansはクラスタ数kを事前に指定する必要があるが、階層的クラスタリングはデンドログラムを作ってから後でクラスタ数を決められる。", "k-meansはクラスタ数を後からデンドログラムを見て自由に決められるが、階層的クラスタリングは計算を始める前に必ず指定しなければならない。", "k-meansも階層的クラスタリングも、どちらも教師ありのラベルを必要とする手法である。", "k-meansと階層的クラスタリングは同じアルゴリズムの別名であり、計算手順も結果も常に一致する。"]', 0, '[0]', 'single', '{"asked": "k-means法と階層的クラスタリングの、クラスタ数の決め方の違い。", "why_asked": "「クラスタ数を先に決められない状況でどちらを使うか」という実務判断に直結する、性質の違いを問う定番。", "kid": "k-meansは「最初にグループ数を決めてから分ける」、階層的クラスタリングは「木を作ってから、後でどこで切るか決める」。", "terms": [["デンドログラム", "階層的クラスタリングの結果を木構造で表した図。どの高さで切るかでクラスタ数が決まる"], ["ウォード法", "階層的クラスタリングでクラスタ内の分散の増加が最小になるように結合していく代表的な方法"]], "think": "k-meansは重心を更新しながらk個のグループに割り振っていく手法で、最初にkを決める必要がある。階層的クラスタリングはデータを1つずつくっつけていきデンドログラム(樹形図)を作り、後から好きな高さで切ってクラスタ数を選べる。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"80\" y=\"16\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">k-means(k=3を先に指定)</text><circle cx=\"50\" cy=\"40\" r=\"4\" fill=\"#6ab08d\"/><circle cx=\"65\" cy=\"55\" r=\"4\" fill=\"#6ab08d\"/><circle cx=\"45\" cy=\"65\" r=\"4\" fill=\"#6ab08d\"/><circle cx=\"110\" cy=\"45\" r=\"4\" fill=\"#c9a04a\"/><circle cx=\"125\" cy=\"60\" r=\"4\" fill=\"#c9a04a\"/><circle cx=\"60\" cy=\"105\" r=\"4\" fill=\"#c47070\"/><circle cx=\"80\" cy=\"115\" r=\"4\" fill=\"#c47070\"/><text x=\"255\" y=\"16\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">階層的(後で切る高さを選ぶ)</text><line x1=\"200\" y1=\"110\" x2=\"200\" y2=\"90\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><line x1=\"230\" y1=\"110\" x2=\"230\" y2=\"90\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><line x1=\"200\" y1=\"90\" x2=\"230\" y2=\"90\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><line x1=\"215\" y1=\"90\" x2=\"215\" y2=\"60\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><line x1=\"280\" y1=\"110\" x2=\"280\" y2=\"60\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><line x1=\"215\" y1=\"60\" x2=\"280\" y2=\"60\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><line x1=\"247\" y1=\"60\" x2=\"247\" y2=\"35\" stroke=\"#60a5fa\" stroke-width=\"2\" stroke-dasharray=\"3,3\"/><line x1=\"200\" y1=\"35\" x2=\"300\" y2=\"35\" stroke=\"#60a5fa\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\"/><text x=\"305\" y=\"38\" fill=\"#60a5fa\" font-size=\"8\">切る高さ</text></svg>", "vs": "k-NN(教師あり・分類)、k-means(教師なし・クラスタリング)、階層的クラスタリング(教師なし・クラスタリング)の3つを混同しない。", "opt": ["正解。k-meansはkを事前指定、階層的クラスタリングはデンドログラムを作ってから後でクラスタ数を選べる。", "説明が入れ替わっている。事前指定が必要なのはk-means、後から決められるのは階層的クラスタリングである。", "k-meansも階層的クラスタリングもラベルを使わない教師なし学習であり、ラベルを必要としない。", "重心を反復更新するk-meansと、木構造を作る階層的クラスタリングでは計算手順が異なり、結果も一般に一致しない。"]}'),
  ('e-shikaku-q18', '2. 機械学習', 'ある2値分類モデルの混同行列がTP=40, FP=10, FN=20, TN=30だったとき、適合率(Precision)と再現率(Recall)はそれぞれどうなるか。', NULL::text, '["適合率は80%、再現率は67%。適合率はTPをTP+FPで割り、再現率はTPをTP+FNで割って求める。", "適合率は67%、再現率は80%。適合率と再現率の分母が入れ替わってしまっている。", "適合率も再現率も同じ57%になる。TPを全体(TP+FP+FN+TN)で割った正解率の考え方を使ってしまっている。", "適合率は40%、再現率は40%。TPの値をそのまま件数のまま使ってしまっている。"]', 0, '[0]', 'single', '{"asked": "混同行列の4つの値から適合率と再現率を計算する手順。", "why_asked": "mAPやF値など、物体検出・分類の評価指標の多くはこの適合率・再現率の組み合わせの上に定義されている。", "kid": "適合率は「陽性と言った予測のうち当たった割合」、再現率は「本当に陽性だったもののうち見つけられた割合」。", "terms": [["適合率(Precision)", "陽性と予測したもののうち、実際に陽性だった割合"], ["再現率(Recall)", "実際に陽性だったもののうち、正しく陽性と予測できた割合"]], "think": "適合率は「予測した陽性」を分母に、再現率は「実際の陽性」を分母に取る。分母がどちらの集合かを間違えると値が入れ替わってしまう。", "calc": "TP=40, FP=10, FN=20, TN=30\n適合率(Precision) = TP ÷ (TP+FP) = 40 ÷ (40+10) = 40 ÷ 50 = 0.8 → 80%\n再現率(Recall) = TP ÷ (TP+FN) = 40 ÷ (40+20) = 40 ÷ 60 ≈ 0.67 → 67%", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">混同行列</text><text x=\"145\" y=\"36\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">実際陽性</text><text x=\"235\" y=\"36\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">実際陰性</text><rect x=\"100\" y=\"42\" width=\"90\" height=\"45\" fill=\"#2a2f3f\" stroke=\"#141720\"/><text x=\"145\" y=\"64\" fill=\"#6ab08d\" font-size=\"13\" text-anchor=\"middle\">TP=40</text><rect x=\"190\" y=\"42\" width=\"90\" height=\"45\" fill=\"#2a2f3f\" stroke=\"#141720\"/><text x=\"235\" y=\"64\" fill=\"#c47070\" font-size=\"13\" text-anchor=\"middle\">FP=10</text><rect x=\"100\" y=\"87\" width=\"90\" height=\"45\" fill=\"#2a2f3f\" stroke=\"#141720\"/><text x=\"145\" y=\"109\" fill=\"#c47070\" font-size=\"13\" text-anchor=\"middle\">FN=20</text><rect x=\"190\" y=\"87\" width=\"90\" height=\"45\" fill=\"#2a2f3f\" stroke=\"#141720\"/><text x=\"235\" y=\"109\" fill=\"#6ab08d\" font-size=\"13\" text-anchor=\"middle\">TN=30</text><text x=\"60\" y=\"64\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">予測陽性</text><text x=\"60\" y=\"109\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">予測陰性</text></svg>", "vs": "F値は適合率と再現率の調和平均で、どちらか一方だけが高くても高くならない指標。ROC曲線・AUCは閾値を変えながら性能を見る指標で、混同行列1つだけでは表せない。", "opt": ["正解。適合率はTP/(TP+FP)=80%、再現率はTP/(TP+FN)≈67%になる。", "適合率と再現率の分母が入れ替わっている。適合率の分母はTP+FP、再現率の分母はTP+FNである。", "正解率はTNも含めた全体を分母にする別の指標であり、適合率・再現率とは分母が異なる。", "TPの件数(40)をそのまま割合として使うのではなく、それぞれの分母で割り算する必要がある。"]}'),
  ('e-shikaku-q19', '3. 深層学習の基礎', '全結合層で、入力x=[1, 2]に重みW=[[1, 0], [0, 1]](単位行列)、バイアスb=[1, 1]を使って出力y=Wx+bを計算するとどうなるか。', NULL::text, '["[2, 3]。単位行列を掛けると入力がそのまま返ってくるので、あとはバイアスを足すだけになる。", "[1, 2]。重みWを掛けた後にバイアスbを足す手順を忘れ、Wxの値をそのまま出力にしてしまっている。", "[1, 1]。入力xを使わず、バイアスbだけを出力にしてしまっている。", "[2, 2]。x1のみを両方の出力に使ってしまっている。"]', 0, '[0]', 'single', '{"asked": "全結合層の基本計算 y=Wx+b を、単位行列を例に手を動かして求める。", "why_asked": "誤差逆伝播法や勾配計算はすべてこのy=Wx+bの形の上に組み立てられるため、行列とベクトルの掛け算・足し算を数値で追える理解が土台になる。", "kid": "入力に重みを掛けて、最後にバイアス(下駄)を履かせるだけの単純な計算。", "terms": [["重み(W)", "入力の各要素をどれだけ重要視するかを決めるパラメータ"], ["バイアス(b)", "入力が全部0でも出力を底上げする、切片のようなパラメータ"]], "think": "全結合層は「入力ベクトルを行列で変換してから、バイアスを足す」だけのシンプルな計算。この後に活性化関数を通すことで非線形性が加わる。", "calc": "重みWは単位行列 → Wx = x (入力がそのまま出てくる)\nWx = [1, 2]\nバイアスを足す : y = Wx + b = [1+1, 2+1] = [2, 3]", "vs": "活性化関数を通す前の値(この問題のy)は「ロジット」と呼ばれ、通した後の値とは区別される。", "opt": ["正解。単位行列を掛けると入力がそのまま出てくるため、Wx=[1,2]にbを足してy=[2,3]になる。", "バイアスbを足す手順が抜けており、Wxだけで計算を止めてしまっている。", "入力xを掛ける手順が抜けており、バイアスbだけをそのまま出力にしてしまっている。", "単位行列は各出力に対応する入力の値をそのまま返すのであって、1つの入力を両方の出力にコピーするわけではない。"]}'),
  ('e-shikaku-q20', '3. 深層学習の基礎', '深層学習モデルの出力層と損失関数の組み合わせとして、正しいものはどれか。', NULL::text, '["回帰には平均二乗誤差(MSE)、多クラス分類にはソフトマックス関数+クロスエントロピー誤差を組み合わせるのが基本形である。", "回帰にはクロスエントロピー誤差、多クラス分類には平均二乗誤差を組み合わせるのが基本形であり、タスクの種類によらず入れ替えても差し支えない。", "回帰でも多クラス分類でも、常にバイナリクロスエントロピーだけを使えばよい。", "出力層の活性化関数と損失関数の組み合わせに決まりはなく、どの組み合わせでも学習の効率は変わらない。"]', 0, '[0]', 'single', '{"asked": "タスクの種類(回帰・2値分類・多クラス分類)ごとの出力層と損失関数の標準的な組み合わせ。", "why_asked": "出力層の設計ミス(タスクに合わない損失関数を使う)は実装時に真っ先につまずくポイントであり、正しい対応関係を覚えているかが問われる。", "kid": "「何を答えさせたいか」によって、出力の形と、答え合わせの仕方(損失関数)のセットが決まっている。", "terms": [["平均二乗誤差(MSE)", "予測値と正解値の差を2乗して平均した回帰用の損失"], ["クロスエントロピー誤差", "予測した確率分布と正解の分布のズレを測る分類用の損失"]], "think": "タスクの性質(連続値か、カテゴリかどうか)に応じて出力層の形と損失関数はセットで決まる。回帰は実数値をそのまま出すのでMSE、多クラス分類は確率分布同士のズレを測りたいのでソフトマックス+クロスエントロピー。", "vs": "2値分類はバイナリクロスエントロピー(出力層はシグモイド1個)、多クラス分類はクロスエントロピー誤差(出力層はソフトマックスでクラス数ぶん)と、クラス数によって出力層の形が変わる。", "opt": ["正解。回帰にはMSE、多クラス分類にはソフトマックス+クロスエントロピー誤差という組み合わせが基本形になる。", "回帰とクロスエントロピー、多クラス分類とMSEの組み合わせは逆であり、連続値にクロスエントロピーは使えない。", "バイナリクロスエントロピーは2値分類用の損失であり、連続値を予測する回帰にはそのままでは使えない。", "タスクに合わない損失関数を使うと学習がうまく進まなくなるため、組み合わせには基本形が存在する。"]}'),
  ('e-shikaku-q21', '3. 深層学習の基礎', 'シグモイド関数とReLU関数を比べたとき、シグモイド関数が深い層のネットワークで学習を難しくしやすい理由として正しいものはどれか。', NULL::text, '["入力が大きい・小さい領域で勾配がほぼ0になり、層を重ねるほど誤差逆伝播中に勾配が掛け算で小さくなっていく(勾配消失)から。", "シグモイド関数の出力が常に負の値になってしまい、そのままでは損失関数(クロスエントロピー等)がそもそも定義できなくなるから。", "計算に平方根が必要で、ReLUよりも計算コストが極端に高くなるから。", "出力が0〜1に収まらず、確率として解釈できなくなるから。"]', 0, '[0]', 'single', '{"asked": "シグモイド関数が深いネットワークで勾配消失を起こしやすい理由。", "why_asked": "ReLU系の活性化関数が主流になった理由そのものであり、活性化関数の選び方の背景を理解しているかを問う定番。", "kid": "シグモイドは両端が平らなグラフなので、何層も通るうちに「傾き」がどんどん小さくなって消えてしまう。", "terms": [["勾配消失", "層を重ねるほど逆伝播の勾配が0に近づき、浅い層のパラメータがほとんど更新されなくなる現象"], ["ReLU", "入力が正ならそのまま、負なら0を返す活性化関数。計算が軽く勾配消失が起きにくい"]], "think": "シグモイドのグラフは両端(入力が大きい・小さい)でほぼ平らになる。誤差逆伝播はこの傾き(勾配)を層をまたいで掛け算でつなげていくので、平らな部分を何層も通ると勾配がどんどん0に近づいてしまう。ReLUは正の領域で傾きが常に1なので、この問題が起きにくい。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"90\" y=\"16\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">シグモイド(両端が平ら)</text><line x1=\"20\" y1=\"70\" x2=\"170\" y2=\"70\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><path d=\"M 20,110 C 60,110 80,20 95,20 C 110,20 130,20 170,20\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"2.5\"/><text x=\"30\" y=\"105\" fill=\"#c47070\" font-size=\"8\">傾きほぼ0</text><text x=\"120\" y=\"28\" fill=\"#c47070\" font-size=\"8\">傾きほぼ0</text><text x=\"235\" y=\"16\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">ReLU(正の領域は傾き一定)</text><line x1=\"185\" y1=\"70\" x2=\"330\" y2=\"70\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><path d=\"M 185,110 L 257,110 L 330,25\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"2.5\"/><text x=\"290\" y=\"45\" fill=\"#6ab08d\" font-size=\"8\">傾き=1</text></svg>", "vs": "tanhもS字カーブでシグモイドと似た勾配消失の弱点を持つが、出力が-1〜1で0を中心にしている点がシグモイド(0〜1)と違う。GELUはReLUを滑らかにした発展形。", "opt": ["正解。シグモイドは両端で勾配がほぼ0になり、層を重ねるほど連鎖律の掛け算で勾配が消えやすくなる。", "シグモイドの出力は0〜1の正の範囲であり、常に負になるわけではない。", "計算コストの差(指数関数を使うかどうか)はあるが、勾配消失の主な原因は計算コストではなく勾配の値そのものが小さくなることである。", "シグモイドの出力はむしろ0〜1に収まるように設計されており、確率として解釈しやすい形になっている。"]}'),
  ('e-shikaku-q22', '3. 深層学習の基礎', '確率的勾配降下法(SGD)でパラメータθを更新する式θ_new = θ - η∇Lを使う。θ=5、学習率η=0.1、勾配∇L=8のとき、更新後のθはどうなるか。', NULL::text, '["4.2。θから学習率×勾配を引く。0.1×8=0.8を5から引く。", "5.8。学習率×勾配を、引くのではなく足してしまっている。", "13。θと勾配をそのまま足してしまい、学習率を掛けていない。", "0.8。学習率×勾配の値そのものを更新後のθとして使ってしまっている。"]', 0, '[0]', 'single', '{"asked": "SGDの更新式にθ・学習率・勾配の具体的な数値を当てはめて、更新後のθを求める。", "why_asked": "最適化アルゴリズムの更新式の「向き」(引くのか足すのか)を正しく理解しているかを問う、実装で最も事故りやすいポイント。", "kid": "勾配が示す方向と逆向きに、学習率ぶんだけθを少し動かす計算。", "terms": [["学習率(η)", "1回の更新でパラメータをどれだけ動かすかを決める係数"], ["ミニバッチ", "全データではなく一部のデータだけで勾配を計算し、更新を繰り返す方式"]], "think": "勾配∇Lは「損失を増やす方向」を指すので、その逆向き(マイナス)にθを動かすと損失が減る。学習率はその一歩の大きさを調整するブレーキ役。", "calc": "学習率 × 勾配 : 0.1 × 8 = 0.8\nθ_new = θ - 0.8 = 5 - 0.8 = 4.2", "vs": "学習率が大きすぎると損失が減るどころか発散し、小さすぎると学習が遅くなる。この後のAdamなどは、この学習率を状況に応じて自動調整する工夫。", "opt": ["正解。学習率×勾配=0.8をθ=5から引くと、更新後のθは4.2になる。", "更新式は勾配の逆向き(引き算)にθを動かすものであり、足し算では損失を減らす方向に進まない。", "学習率を掛けずにθと勾配をそのまま足すと、更新の大きさが学習率で調整されず不適切な計算になる。", "学習率×勾配の値(0.8)はθから引く量であって、更新後のθそのものではない。"]}'),
  ('e-shikaku-q23', '3. 深層学習の基礎', '深層学習の最適化アルゴリズムはSGD→モメンタム→RMSProp→Adamという順に発展してきたとされる。Adamがモメンタムのアイデアと組み合わせている工夫として正しいものはどれか。', NULL::text, '["RMSPropの「パラメータごとに学習率を自動調整する」仕組みを組み合わせている。過去の勾配の向きを覚える(モメンタム)のと、勾配の大きさに応じて学習率を変える(RMSProp)の両方を使う。", "L1正則化の仕組みを組み合わせている。損失関数に重みの絶対値の合計をペナルティとして加えることで不要なパラメータをちょうど0にし、疎な解を作る工夫であり、パラメータごとの学習率の自動調整そのものとは別の話である。", "ドロップアウトの仕組みを組み合わせている。ニューロンをランダムに無効化する工夫であり、最適化アルゴリズムの更新式とは別の話。", "早期終了の仕組みを組み合わせている。学習を途中で打ち切る工夫であり、パラメータの更新式そのものには関与しない。"]', 0, '[0]', 'single', '{"asked": "Adamが「モメンタム」に加えて組み合わせているもう1つの工夫の正体。", "why_asked": "Adamという名前を覚えるだけでなく、SGD→モメンタム→RMSProp→Adamという発展の系譜(何が足されてきたか)を理解しているかが問われる。", "kid": "Adamは「これまでの勢いを覚えておく」工夫と「パラメータごとに歩幅を自動調整する」工夫を合体させたアルゴリズム。", "terms": [["モメンタム", "過去の勾配の移動平均を使って更新方向に慣性を持たせる工夫"], ["RMSProp", "勾配の2乗の移動平均を使って、パラメータごとに学習率を自動調整する工夫"]], "think": "モメンタムは「これまでの更新方向を慣性のように引き継ぐ」工夫、RMSPropは「勾配が大きく動く方向は学習率を小さく、動きが少ない方向は学習率を大きく」自動調整する工夫。Adamはこの2つを合体させたアルゴリズム。", "vs": "パラメータの初期化戦略(Xavier法/He法)は「学習を始める前」の工夫、最適化アルゴリズム(Adam等)は「学習中の更新の仕方」の工夫で、別のレイヤーの話。", "opt": ["正解。AdamはモメンタムとRMSPropの両方のアイデアを組み合わせ、慣性と自動学習率調整を両立させている。", "L1正則化は損失関数にペナルティを足す仕組みであり、Adamの更新式そのものの構成要素ではない。", "ドロップアウトはネットワーク構造側の正則化であり、Adamのようなパラメータ更新式の工夫とは別の仕組みである。", "早期終了は学習を止めるタイミングの工夫であり、Adamの更新式(学習率の自動調整)そのものとは別の仕組みである。"]}'),
  ('e-shikaku-q24', '3. 深層学習の基礎', '誤差逆伝播法で、y=f(g(x))のように関数が入れ子になっているとき、xについての勾配dy/dxを求めるために使われる考え方はどれか。', NULL::text, '["連鎖律。dy/dx = dy/dg × dg/dxのように、途中の変数を介して勾配を掛け算でつなげていく。", "最小二乗法。予測値と正解値の差を2乗した合計を最小化するという損失の定義であり、合成関数の勾配をどう計算するかという手順そのものの説明ではない。", "ベイズの定理。条件付き確率を逆算する考え方であり、微分の計算とは無関係。", "主成分分析。データの分散が大きい方向を探す考え方であり、勾配の計算手順ではない。"]', 0, '[0]', 'single', '{"asked": "合成関数の微分をどう計算するか、という誤差逆伝播法の理論的な土台。", "why_asked": "誤差逆伝播法・自動微分の仕組みそのものであり、E資格で最も重視される「なぜ動くか」の核心部分。", "kid": "出力側の誤差を、層をひとつずつさかのぼりながら「掛け算」で入力側まで伝えていく考え方。", "terms": [["連鎖律(chain rule)", "合成関数の微分を、途中の変数を介した掛け算の連続に分解できるという微分のルール"], ["計算グラフ", "計算の手順をノードと矢印で表した図。自動微分はこのグラフを逆向きにたどって勾配を求める"]], "think": "ニューラルネットワークは層を重ねた合成関数なので、出力層の誤差から入力層に向かって「1つ前の層までの勾配」を連鎖律で順番に掛け算しながら伝えていく。これが誤差逆伝播法の正体。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">計算グラフ：順伝播と逆伝播</text><rect x=\"30\" y=\"35\" width=\"45\" height=\"30\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"52\" y=\"55\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\">x</text><rect x=\"135\" y=\"35\" width=\"45\" height=\"30\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"157\" y=\"55\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\">g(x)</text><rect x=\"240\" y=\"35\" width=\"45\" height=\"30\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"262\" y=\"55\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\">y=f(g)</text><line x1=\"75\" y1=\"50\" x2=\"135\" y2=\"50\" stroke=\"#60a5fa\" stroke-width=\"2\" marker-end=\"url(#fwd)\"/><line x1=\"180\" y1=\"50\" x2=\"240\" y2=\"50\" stroke=\"#60a5fa\" stroke-width=\"2\" marker-end=\"url(#fwd)\"/><text x=\"170\" y=\"30\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">順伝播 →</text><line x1=\"240\" y1=\"95\" x2=\"180\" y2=\"95\" stroke=\"#c9a04a\" stroke-width=\"2\" marker-end=\"url(#bwd)\"/><line x1=\"135\" y1=\"95\" x2=\"75\" y2=\"95\" stroke=\"#c9a04a\" stroke-width=\"2\" marker-end=\"url(#bwd)\"/><text x=\"170\" y=\"112\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\">← 逆伝播：dy/dg × dg/dx</text><defs><marker id=\"fwd\" markerWidth=\"7\" markerHeight=\"7\" refX=\"3.5\" refY=\"3.5\" orient=\"auto\"><path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"#60a5fa\"/></marker><marker id=\"bwd\" markerWidth=\"7\" markerHeight=\"7\" refX=\"3.5\" refY=\"3.5\" orient=\"auto\"><path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"#c9a04a\"/></marker></defs></svg>", "vs": "「勾配消失」は連鎖律の掛け算の途中に小さい値(シグモイドの平らな部分など)が混ざることで起きる副作用であり、連鎖律そのものの欠陥ではない。", "opt": ["正解。連鎖律は合成関数の微分を、途中の変数を介した勾配の掛け算に分解できるというルールである。", "最小二乗法は損失の定義の話であり、勾配をどう計算するか(連鎖律)そのものの説明ではない。", "ベイズの定理は条件付き確率を逆算する考え方であり、微分の連鎖律とは異なる分野の道具である。", "主成分分析は分散が大きい方向を探す手法であり、合成関数の微分を求める手順とは無関係である。"]}'),
  ('e-shikaku-q25', '3. 深層学習の基礎', '深層学習のパラメータ初期化で、Xavier法(Glorot法)やKaiming法(He法)のように「層の入出力のユニット数に応じて初期値の分散を調整する」工夫が必要な理由として正しいものはどれか。', NULL::text, '["初期値が大きすぎたり小さすぎたりすると、層を重ねるうちに信号の分散が爆発または消失し、学習がうまく始まらないから。", "初期値の分散さえ適切に選んでおけば、その後の学習率やバッチサイズといった他のハイパーパラメータを一切調整しなくても、必ず最も高い精度に到達できるから。", "初期値の分散を調整すると、正則化(L1/L2)を使わなくても過学習が完全に防げるから。", "初期値をすべて同じ値に揃えることで、学習の再現性を保証するため必要になるから。"]', 0, '[0]', 'single', '{"asked": "Xavier法/He法のような分散を考慮した初期化が必要とされる理由。", "why_asked": "初期化戦略は学習の「出だし」を左右する要素であり、勾配消失・勾配爆発という同じ章のテーマとつながっている。", "kid": "最初の重みが大きすぎたり小さすぎたりすると、層を通るたびに信号がどんどん膨らんだりしぼんだりして、学習がうまく始まらない。", "terms": [["Xavier法/Glorot法", "シグモイドやtanhに向いた初期化。前後の層のユニット数から分散を決める"], ["Kaiming法/He法", "ReLU系に向いた初期化。ReLUで出力の半分が0になることを考慮して分散を大きめに取る"]], "think": "すべて同じ値やランダムすぎる値で初期化すると、順伝播や逆伝播の途中で信号(値や勾配)がどんどん大きくor小さくなってしまう。層のユニット数を考慮した分散で初期化すると、信号の大きさが層を通しても保たれやすくなる。", "vs": "バッチ正規化は学習「中」に各層の分布を整える工夫、初期化戦略は学習を「始める前」に整える工夫で、役割が違う(併用されることも多い)。", "opt": ["正解。初期値が適切な分散でないと信号が層を通るたびに爆発・消失し、学習が始まりにくくなる。", "初期化を工夫しても学習率やバッチサイズなど他のハイパーパラメータの調整は依然として必要であり、それだけで精度が保証されるわけではない。", "初期化は学習の出だしを整える工夫であり、正則化(L1/L2やドロップアウト)の代わりに過学習を防ぐものではない。", "すべて同じ値にすると、同じ層内のユニットが同じ更新をし続けて区別がつかなくなる問題が起きるため、むしろ避けるべきやり方である。"]}'),
  ('e-shikaku-q26', '3. 深層学習の基礎', '深層モデルの正則化のうち、パラメータノルムペナルティー(L1/L2正則化)と確率的削除(ドロップアウト)の違いとして正しいものはどれか。', NULL::text, '["L1/L2正則化は損失関数に重みの大きさに応じたペナルティを足す方法、ドロップアウトは学習時にランダムにニューロンを無効化してアンサンブルのような効果を狙う方法。", "L1/L2正則化は学習のたびにニューロンをランダムに無効化する方法、ドロップアウトは損失関数に重みの大きさに応じたペナルティ項を足す方法であり、それぞれの説明が入れ替わってしまっている。", "L1/L2正則化もドロップアウトも、どちらも学習後の推論時にだけ働く仕組みである。", "L1/L2正則化とドロップアウトは同じ数式を別名で呼んでいるだけで、実際の計算処理は同じである。"]', 0, '[0]', 'single', '{"asked": "L1/L2正則化とドロップアウトという、アプローチが異なる2種類の正則化の違い。", "why_asked": "「正則化」とひとくくりにされがちな手法群を、損失関数側の工夫かネットワーク構造側の工夫かで区別できるかを問う。", "kid": "L1/L2は「重みが大きくなりすぎたら罰金」、ドロップアウトは「毎回一部のニューロンをお休みさせる」という別のアプローチ。", "terms": [["weight decay", "L2正則化と実質同じ効果を持つ、重みを少しずつ減衰させる実装上の工夫"], ["ドロップコネクト", "ニューロン単位ではなく、重みの接続そのものをランダムに切る、ドロップアウトの発展形"]], "think": "L1/L2正則化は「重みが大きくなりすぎないように罰金を科す」発想、ドロップアウトは「毎回違う一部のニューロンだけで学習させることで、特定のニューロンに依存しすぎないようにする」発想。アプローチの層が違う(損失関数側 vs ネットワーク構造側)。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">ドロップアウト：一部のニューロンを無効化</text><circle cx=\"60\" cy=\"40\" r=\"8\" fill=\"#3b82f6\"/><circle cx=\"60\" cy=\"70\" r=\"8\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/><text x=\"60\" y=\"74\" fill=\"#c47070\" font-size=\"9\" text-anchor=\"middle\">×</text><circle cx=\"60\" cy=\"100\" r=\"8\" fill=\"#3b82f6\"/><circle cx=\"170\" cy=\"30\" r=\"8\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/><text x=\"170\" y=\"34\" fill=\"#c47070\" font-size=\"9\" text-anchor=\"middle\">×</text><circle cx=\"170\" cy=\"70\" r=\"8\" fill=\"#3b82f6\"/><circle cx=\"170\" cy=\"110\" r=\"8\" fill=\"#3b82f6\"/><circle cx=\"280\" cy=\"70\" r=\"8\" fill=\"#60a5fa\"/><line x1=\"68\" y1=\"40\" x2=\"162\" y2=\"70\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"68\" y1=\"100\" x2=\"162\" y2=\"70\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"68\" y1=\"100\" x2=\"162\" y2=\"110\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"178\" y1=\"70\" x2=\"272\" y2=\"70\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"178\" y1=\"110\" x2=\"272\" y2=\"70\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"170\" y=\"130\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">×印のニューロンはその回だけ計算から除外される</text></svg>", "vs": "早期終了(early stopping)は損失関数もネットワーク構造も変えず、学習を打ち切るタイミングだけで過学習を防ぐ「陰的正則化」で、この2つとはさらに別のアプローチ。", "opt": ["正解。L1/L2正則化は損失関数へのペナルティ、ドロップアウトはニューロンのランダムな無効化という異なるアプローチである。", "説明が入れ替わっている。ニューロンを無効化するのはドロップアウト、損失関数にペナルティを足すのはL1/L2正則化である。", "ドロップアウトは学習時にはランダムに無効化を行うが、推論時には基本的に全ニューロンを使う(出力をスケール調整する)ため、学習時にも働く仕組みである。", "L1/L2正則化とドロップアウトは働きかける対象(損失関数か、ネットワーク構造か)が異なる別の仕組みである。"]}'),
  ('e-shikaku-q27', '3. 深層学習の基礎', '学習を続けるほど訓練誤差は下がり続けるが、検証誤差はあるところから上がり始めることがある。このタイミングで学習を打ち切る「早期終了(early stopping)」が防ごうとしている現象はどれか。', NULL::text, '["過学習(overfitting)。訓練データのノイズまで覚え始め、新しいデータへの性能(汎化性能)が落ち始めるタイミングを見極めて止める。", "過少適合(underfitting)。モデルの表現力が最初から不足していて訓練データにすら当てはまらない状態であり、学習を途中で打ち切っても解決しない種類の問題である。", "勾配消失。層を重ねすぎて勾配が伝わらなくなる現象であり、学習を打ち切るタイミングとは無関係。", "モード崩壊。GANの学習で生成結果の多様性が失われる現象であり、通常の教師あり学習の早期終了とは別の話。"]', 0, '[0]', 'single', '{"asked": "早期終了(early stopping)が防ごうとしている具体的な現象。", "why_asked": "「陰的正則化」という分類のもとに置かれる早期終了が、実際には何を検知して止めているのかを理解しているかを問う。", "kid": "訓練データの点数だけが伸び続けて、新しいデータへの実力が落ち始めた瞬間に勉強をやめる、という工夫。", "terms": [["検証誤差", "学習には使わない検証データに対する誤差。汎化性能の目安"], ["ハイパーパラメータ", "学習率やバッチサイズのように、学習前に人が決めるパラメータ。早期終了の「何エポックで止めるか」もその一つ"]], "think": "訓練誤差は下がり続けても、検証誤差が底を打って上がり始めた瞬間が「訓練データを覚えすぎ始めた」サイン。そこで学習を止めれば、モデル構造も損失関数もいじらずに過学習を抑えられる。", "vs": "バッチサイズや学習率の調整も陰的正則化の一種に分類されるが、早期終了は「学習の長さ」そのものを調整する点が特徴。", "opt": ["正解。検証誤差が上がり始める(過学習が始まる)タイミングを見極めて学習を打ち切るのが早期終了の目的である。", "過少適合は学習が足りないのではなく表現力不足の問題であり、学習を打ち切ることで解決する種類の問題ではない。", "勾配消失は層の深さや活性化関数に起因する問題であり、学習を打ち切るタイミングの調整では解決しない。", "モード崩壊はGAN特有の生成結果の多様性の問題であり、通常の教師あり学習における早期終了の対象ではない。"]}'),
  ('e-shikaku-q28', '3. 深層学習の基礎', '入力サイズ7×7、カーネルサイズ3×3、パディング0、ストライド2の畳み込みを行うと、出力の1辺のサイズはいくつになるか(式: O=⌊(I-K+2P)/S⌋+1)。', NULL::text, '["3。(7-3+0)/2=2に1を足して3になる。", "4。ストライドで割る前の(7-3+0)=4を、そのまま答えにしてしまっている。", "2。1を足すのを忘れてしまっている。", "5。パディングを2として計算してしまっている。"]', 0, '[0]', 'single', '{"asked": "畳み込み演算の出力サイズを、公式に数値を当てはめて求める。", "why_asked": "CNNの層を設計するときに必須の計算であり、E資格の計算問題として最も定番の形の1つ。", "kid": "カーネル(小さい窓)が入力の上を何回置けるかを数える計算。", "terms": [["パディング(P)", "入力の周りに0などを埋めて、出力サイズを調整するテクニック"], ["ストライド(S)", "カーネルを何マスずつずらしながら畳み込むかを表す間隔"]], "think": "カーネルが動ける範囲(I-K+2P)を、ストライドで割ればカーネルが何回置けるかが分かり、最初の1回分を足すと出力サイズになる。", "calc": "I=7, K=3, P=0, S=2\nI - K + 2P = 7 - 3 + 0 = 4\n4 ÷ S = 4 ÷ 2 = 2\n最後に+1する : 2 + 1 = 3\n→ 出力は 3×3", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">7×7の入力を3×3カーネルがストライド2で動く</text><g transform=\"translate(60,25)\"><rect x=\"0\" y=\"0\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"20\" y=\"0\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"40\" y=\"0\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"60\" y=\"0\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"80\" y=\"0\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"100\" y=\"0\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"120\" y=\"0\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"0\" y=\"13\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"20\" y=\"13\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"40\" y=\"13\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"60\" y=\"13\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"80\" y=\"13\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"100\" y=\"13\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"120\" y=\"13\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"0\" y=\"26\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"20\" y=\"26\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"40\" y=\"26\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"60\" y=\"26\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"80\" y=\"26\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"100\" y=\"26\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"120\" y=\"26\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"0\" y=\"39\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"20\" y=\"39\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"40\" y=\"39\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"60\" y=\"39\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"80\" y=\"39\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"100\" y=\"39\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"120\" y=\"39\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"0\" y=\"52\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"20\" y=\"52\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"40\" y=\"52\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"60\" y=\"52\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"80\" y=\"52\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"100\" y=\"52\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"120\" y=\"52\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"0\" y=\"65\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"20\" y=\"65\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"40\" y=\"65\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"60\" y=\"65\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"80\" y=\"65\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"100\" y=\"65\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"120\" y=\"65\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"0\" y=\"78\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"20\" y=\"78\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"40\" y=\"78\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"60\" y=\"78\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"80\" y=\"78\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"100\" y=\"78\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"120\" y=\"78\" width=\"20\" height=\"13\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"0\" y=\"0\" width=\"60\" height=\"39\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"2.5\"/><rect x=\"40\" y=\"26\" width=\"60\" height=\"39\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"2\" stroke-dasharray=\"3,2\"/></g><text x=\"170\" y=\"128\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">2マスずつずらして置ける回数+1 = 3回 → 出力3×3</text></svg>", "vs": "特徴マップ(出力)のチャネル数はカーネルの数で決まり、この式(空間サイズ)とは別に数える必要がある。", "opt": ["正解。(7-3+0)÷2=2に1を足して、出力サイズは3になる。", "ストライドで割る手順が抜けており、カーネルが動ける範囲の広さ(4)をそのまま出力サイズにしてしまっている。", "割り算の結果(2)に、最初の1回分を足す「+1」の手順が抜けている。", "パディングは問題文の通り0であり、2として計算すると出力サイズが変わってしまう。"]}'),
  ('e-shikaku-q29', '3. 深層学習の基礎', 'Max poolingとGlobal Average Pooling(GAP)の違いとして正しいものはどれか。', NULL::text, '["Max poolingは小さな窓ごとに最大値を残して特徴マップを縮小するのに対し、GAPはチャネルごとに特徴マップ全体の平均を取って1つの値にまとめる。", "Max poolingはチャネル全体の特徴マップを平均して1つの値にまとめ、GAPは小さな窓ごとに最大値だけを残す演算であり、それぞれの説明が入れ替わってしまっている。", "Max poolingもGAPも学習可能な重みを持ち、畳み込み層と同じようにパラメータを更新する。", "Max poolingとGAPはどちらもチャネル数を半分に減らすための演算で、空間サイズには影響しない。"]', 0, '[0]', 'single', '{"asked": "Max poolingとGlobal Average Poolingの、縮小のスケール(窓ごとか、全体一括か)の違い。", "why_asked": "GAPは全結合層の直前でパラメータ数を大きく減らす目的でよく使われるため、Max poolingとの役割の違いを理解しているかが問われる。", "kid": "Max poolingは「小さい窓の中で一番目立つ値」を残す、GAPは「チャネル全体をならして1個の数字」にまとめる。", "terms": [["特徴マップ", "畳み込み層の出力。フィルタが検出した特徴の強さを空間的に並べたもの"], ["Lp pooling", "Max poolingや平均プーリングを一般化した、Lpノルムに基づくプーリング"]], "think": "Max poolingは「窓の中で一番目立つ特徴を残す」ダウンサンプリング。GAPは全結合層の直前などで使われ、「そのチャネルの特徴マップ全体をならして1個の数字に要約する」ことで、位置に関する情報を思い切って捨てる代わりにパラメータ数を大きく減らせる。", "vs": "ストライド付き畳み込みでも空間サイズを縮小できるが、プーリングは学習パラメータを持たない点が畳み込み層と違う。", "opt": ["正解。Max poolingは窓ごとの最大値、GAPはチャネル全体の平均を1つの値にまとめる演算である。", "説明が入れ替わっている。窓ごとの最大値を残すのはMax pooling、全体を1つにまとめるのはGAPである。", "プーリング層は一般に学習可能な重みを持たない演算であり、畳み込み層とはその点で異なる。", "Max poolingは主に空間サイズ(縦横)を縮小する演算であり、チャネル数を半分にする演算ではない。"]}'),
  ('e-shikaku-q30', '3. 深層学習の基礎', '通常のRNNで系列が長くなるほど「昔の情報」が勾配消失によって伝わりにくくなる問題を、LSTMが緩和するために導入した仕組みはどれか。', NULL::text, '["ゲート機構(忘却ゲート・入力ゲート・出力ゲート)とメモリーセル。情報を保持・更新する経路を用意し、勾配が消えにくくしている。", "畳み込み演算。フィルタを使って空間的な特徴を抽出する仕組みであり、時系列の記憶を保持する仕組みではない。", "ドロップアウト。学習時にニューロンをランダムに無効化する正則化の仕組みであり、長期記憶の保持とは無関係。", "Positional Encoding。系列の位置情報を埋め込む仕組みであり、Transformerで使われるもので、LSTMのゲート機構とは別物。"]', 0, '[0]', 'single', '{"asked": "LSTMが通常のRNNの勾配消失問題を緩和するために導入した仕組み。", "why_asked": "RNN→LSTM→GRU→Transformerという系列モデルの発展の出発点であり、なぜLSTMが必要とされたかを理解する土台になる。", "kid": "LSTMは「何を忘れて、何を新しく覚えて、何を外に出すか」を毎回調整できる、記憶帳のような仕組みを持っている。", "terms": [["忘却ゲート", "メモリーセルの情報のうち、どれだけ忘れるかを調整するゲート"], ["GRU", "LSTMを簡略化し、ゲートの数を減らした発展形。リセットゲートと更新ゲートを持つ"]], "think": "通常のRNNはBPTT(時間方向の逆伝播)で同じ重み行列を繰り返し掛け算するため、系列が長いほど勾配が消えたり爆発したりしやすい。LSTMはメモリーセルという「情報を流し続ける経路」を用意し、ゲートで「何を忘れ、何を新しく取り入れ、何を出力するか」を調整することで、この問題を緩和する。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">LSTMセル：メモリーセルと3つのゲート</text><line x1=\"20\" y1=\"40\" x2=\"320\" y2=\"40\" stroke=\"#60a5fa\" stroke-width=\"3\"/><text x=\"20\" y=\"30\" fill=\"#60a5fa\" font-size=\"9\">メモリーセル(情報が流れ続ける経路)</text><rect x=\"70\" y=\"70\" width=\"55\" height=\"30\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.5\"/><text x=\"97\" y=\"90\" fill=\"#c47070\" font-size=\"9\" text-anchor=\"middle\">忘却ゲート</text><rect x=\"145\" y=\"70\" width=\"55\" height=\"30\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><text x=\"172\" y=\"90\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\">入力ゲート</text><rect x=\"220\" y=\"70\" width=\"55\" height=\"30\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><text x=\"247\" y=\"90\" fill=\"#6ab08d\" font-size=\"9\" text-anchor=\"middle\">出力ゲート</text><line x1=\"97\" y1=\"70\" x2=\"97\" y2=\"40\" stroke=\"#c47070\" stroke-width=\"1.5\"/><line x1=\"172\" y1=\"70\" x2=\"172\" y2=\"40\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><line x1=\"247\" y1=\"70\" x2=\"247\" y2=\"40\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><text x=\"170\" y=\"122\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">3つのゲートが「忘れる・取り入れる・出す」割合を調整する</text></svg>", "vs": "双方向RNNは「過去→未来」だけでなく「未来→過去」方向の情報も使う工夫で、勾配消失対策とは別の目的(文脈の両方向を見る)。", "opt": ["正解。ゲート機構とメモリーセルにより、情報を保持・更新する経路を用意して勾配消失を緩和している。", "畳み込み演算は空間的な特徴抽出のための仕組みであり、時系列の長期記憶を保持する目的の仕組みではない。", "ドロップアウトは正則化の仕組みであり、長期記憶の保持を目的としたLSTM特有の工夫ではない。", "Positional EncodingはTransformerで使われる位置情報の埋め込みであり、LSTMのゲート機構とは異なる仕組みである。"]}'),
  ('e-shikaku-q31', '3. 深層学習の基礎', 'TransformerのSelf-AttentionとSource Target Attention(Encoder-Decoder Attention)の違いとして正しいものはどれか。', NULL::text, '["Self-Attentionは同じ系列内のトークン同士で関連度を計算するのに対し、Source Target AttentionはDecoder側のトークンがEncoder側の出力を参照して関連度を計算する。", "Self-AttentionはDecoder側のトークンがEncoder側の出力を参照して計算し、Source Target Attentionは同じ系列内のトークン同士だけで計算するという、それぞれの説明が入れ替わってしまっている。", "Self-AttentionもSource Target Attentionも、どちらも必ず同じ系列内だけで完結する計算である。", "Self-Attentionは畳み込み演算の別名であり、Attention機構とは異なる仕組みである。"]', 0, '[0]', 'single', '{"asked": "Self-AttentionとSource Target Attentionの、クエリ・キーの参照先の違い。", "why_asked": "Transformerの内部構造(EncoderとDecoderのどこでどのAttentionが使われるか)を理解しているかを問う頻出ポイント。", "kid": "Self-Attentionは「自分の文の中で単語同士が見つめ合う」、Source Target Attentionは「訳文を作る側が原文の方を見る」。", "terms": [["Scaled Dot-Product Attention", "QとKの内積を次元数の平方根で割ってから正規化する、Attentionの基本計算式"], ["Multi-Head Attention", "Attentionを複数のヘッド(視点)に分けて並列に計算し、あとで結合する仕組み"]], "think": "Attentionは「クエリ(Q)がキー(K)にどれだけ注目するか」を計算する仕組み。Self-AttentionはQ・K・Vすべてが同じ系列から作られる。Source Target AttentionはQがDecoder側、K・VがEncoder側から作られ、「出力を作る単語が、入力文のどこに注目すべきか」を計算する。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"90\" y=\"16\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">Self-Attention</text><rect x=\"30\" y=\"35\" width=\"30\" height=\"20\" fill=\"none\" stroke=\"#3b82f6\"/><rect x=\"70\" y=\"35\" width=\"30\" height=\"20\" fill=\"none\" stroke=\"#3b82f6\"/><rect x=\"110\" y=\"35\" width=\"30\" height=\"20\" fill=\"none\" stroke=\"#3b82f6\"/><path d=\"M 45,55 Q 90,80 125,55\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 45,55 Q 65,68 85,55\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1\" opacity=\"0.6\"/><text x=\"255\" y=\"16\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">Source Target Attention</text><rect x=\"265\" y=\"32\" width=\"34\" height=\"20\" fill=\"none\" stroke=\"#6ab08d\"/><text x=\"282\" y=\"66\" fill=\"#6ab08d\" font-size=\"8\" text-anchor=\"middle\">Decoder(Q)</text><rect x=\"190\" y=\"76\" width=\"30\" height=\"20\" fill=\"none\" stroke=\"#c9a04a\"/><rect x=\"228\" y=\"76\" width=\"30\" height=\"20\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"228\" y=\"110\" fill=\"#c9a04a\" font-size=\"8\" text-anchor=\"middle\">Encoder出力(K,V)</text><path d=\"M 282,52 Q 260,64 220,80\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/></svg>", "vs": "Masked Attentionは未来のトークンを見えないようにマスクする工夫で、Decoder側のSelf-Attentionで使われる。参照範囲の違いとは別の軸の話。", "opt": ["正解。Self-Attentionは同一系列内、Source Target AttentionはDecoderからEncoder出力を参照する構造である。", "説明が入れ替わっている。同じ系列内で完結するのがSelf-Attention、Encoder出力を参照するのがSource Target Attentionである。", "Source Target AttentionはDecoder側からEncoder側を参照する構造であり、同じ系列内だけで完結する計算ではない。", "Self-Attentionは畳み込み演算とは異なる、クエリ・キー・バリューを使った独自の重み付け機構である。"]}'),
  ('e-shikaku-q32', '3. 深層学習の基礎', '正規化のBatch NormalizationとLayer Normalizationの違いとして正しいものはどれか。', NULL::text, '["Batch Normalizationはミニバッチ内の同じチャネルをまたいで正規化するのに対し、Layer Normalizationは1つのサンプル内の全チャネル(特徴)をまたいで正規化する、正規化を行う軸が異なる手法である。", "Batch Normalizationは1つのサンプル内の全チャネルをまたいで正規化し、Layer Normalizationはミニバッチ内の同じチャネルをまたいで正規化するという、それぞれの正規化を行う軸の説明が入れ替わってしまっている。", "Batch NormalizationもLayer Normalizationも、学習中にだけ使われる仕組みであり、学習を終えた後の推論時には一切使われることがない。", "Batch NormalizationとLayer Normalizationは正規化する軸の選び方が違うだけで、実際に計算している数式そのものは完全に同じものである。"]', 0, '[0]', 'single', '{"asked": "Batch NormalizationとLayer Normalizationの、正規化を行う軸(バッチ方向かサンプル内か)の違い。", "why_asked": "TransformerがLayer Normalizationを標準採用している理由(可変長系列・小さいバッチサイズへの強さ)を理解する土台になる。", "kid": "Batch Normは「同じ仲間のデータ同士」をならす、Layer Normは「1人のデータの中の特徴同士」をならす。", "terms": [["Instance Normalization", "1サンプルの1チャネルだけで正規化する、スタイル変換などで使われる方式"], ["Group Normalization", "チャネルをいくつかのグループに分けて正規化する、バッチサイズが小さいときに有効な方式"]], "think": "Batch Normalizationは「ミニバッチ内で同じ特徴同士」をならすため、バッチサイズが小さいと統計量が不安定になりやすい。Layer Normalizationは「1サンプルの中の特徴同士」をならすのでバッチサイズに依存せず、系列長が変わるTransformerやRNNと相性が良い。", "vs": "データ拡張(MixUpやRandom Cropなど)は「入力データを増やす」工夫、正規化層は「ネットワーク内部の値の分布を整える」工夫で、汎化性能向上のテクニックという同じ章の中でも役割が違う。", "opt": ["正解。Batch Normalizationはミニバッチ方向、Layer Normalizationはサンプル内の特徴方向で正規化する。", "説明が入れ替わっている。ミニバッチをまたいで正規化するのはBatch Normalization、1サンプル内で完結するのはLayer Normalizationである。", "両者とも学習時だけでなく、推論時にも(学習時の統計量やその場の値を使って)正規化の処理自体は行われる。", "正規化の軸(バッチ方向かサンプル内の特徴方向か)が異なるため、計算式は同じではない。"]}'),
  ('e-shikaku-q33', '4. 深層学習の応用', 'ResNetがネットワークを非常に深くしても学習が破綻しにくいように導入した工夫はどれか。', NULL::text, '["skip connection(残差接続)。入力をそのまま数層先の出力に足し合わせることで、勾配が短い経路でも伝わるようにしている。", "ドロップアウト。学習のたびにニューロンをランダムに無効化する正則化の工夫であり、層を深くしたときの勾配消失対策として設計されたものではない。", "Global Average Pooling。特徴マップを1つの値に要約する演算であり、層を深くする工夫ではない。", "バッチサイズの拡大。1回の更新に使うデータ数を増やす工夫であり、ネットワークの構造上の工夫ではない。"]', 0, '[0]', 'single', '{"asked": "ResNetが非常に深いネットワークでも学習を成立させるために導入した構造上の工夫。", "why_asked": "「層を深くするほど精度が上がるとは限らない」という発見への回答であり、CNNの発展史で最も重要な工夫の1つ。", "kid": "入力をショートカットでそのまま先に渡しておき、各層は「差分だけ」を学習すればよいようにする工夫。", "terms": [["残差(residual)", "入力と目標の出力との差分。ResNetの各ブロックはこの差分を学習する"], ["ボトルネック構造", "1x1畳み込みで一度チャネル数を減らしてから3x3畳み込みを行い、また1x1で戻す、計算量を抑えた設計"]], "think": "層をただ増やすと、恒等写像(何もしない変換)すら学習しづらくなり、逆に精度が落ちることがある(勾配消失が主因)。skip connectionは「入力xをそのまま足す」経路を用意することで、その層は「残差(元の値との差分)」だけを学習すればよくなり、深い層でも勾配が伝わりやすくなる。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">Residual Block：入力を足し合わせる経路</text><rect x=\"30\" y=\"55\" width=\"40\" height=\"24\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"50\" y=\"70\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">入力x</text><rect x=\"120\" y=\"30\" width=\"70\" height=\"24\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"155\" y=\"46\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">畳み込み層</text><rect x=\"230\" y=\"30\" width=\"70\" height=\"24\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"265\" y=\"46\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">畳み込み層</text><line x1=\"70\" y1=\"67\" x2=\"120\" y2=\"42\" stroke=\"#60a5fa\" stroke-width=\"2\"/><line x1=\"190\" y1=\"42\" x2=\"230\" y2=\"42\" stroke=\"#60a5fa\" stroke-width=\"2\"/><line x1=\"70\" y1=\"67\" x2=\"300\" y2=\"67\" stroke=\"#c9a04a\" stroke-width=\"2\" stroke-dasharray=\"4,3\"/><circle cx=\"300\" cy=\"54\" r=\"10\" fill=\"none\" stroke=\"#e8eaf0\" stroke-width=\"1.5\"/><text x=\"300\" y=\"58\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\">+</text><text x=\"230\" y=\"90\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\">skip connection(入力をそのまま迂回させる)</text></svg>", "vs": "DenseNetは「後ろの層すべてに前の層の出力を連結する」という、skip connectionをさらに発展させた設計。", "opt": ["正解。skip connectionで入力を数層先に足し合わせ、各層が残差だけを学習すればよいようにしている。", "ドロップアウトは学習時にニューロンを無効化する正則化であり、深いネットワークの勾配消失を防ぐために設計された仕組みではない。", "Global Average Poolingは特徴マップを要約する演算であり、層を深くしても学習が破綻しにくくする工夫ではない。", "バッチサイズの拡大は学習の効率に関わるハイパーパラメータであり、ネットワーク構造上の勾配消失対策ではない。"]}'),
  ('e-shikaku-q34', '4. 深層学習の応用', 'Vision Transformer(ViT)が画像をTransformerに入力する前に行う前処理として正しいものはどれか。', NULL::text, '["画像を固定サイズのパッチ(小さな正方形)に分割し、各パッチを1つのトークンのように扱ってPosition embeddingを加える。", "画像全体に何段もの畳み込み層をあらかじめ順番に通してから、最終的にできた特徴マップの1マスをそのままCNNの流儀で1トークンとして扱う。", "画像をあらかじめ白黒のグレースケールに変換したうえで、色情報を失ったピクセルを縦横1つずつバラバラの独立したトークンとして扱う。", "画像全体をあらかじめ周波数領域にフーリエ変換したうえで、得られた周波数成分の値をそのままトークンの並びとして順番に扱う。"]', 0, '[0]', 'single', '{"asked": "ViTが画像をTransformerの入力形式に変換するための前処理。", "why_asked": "Transformerは本来「トークンの並び」を扱う仕組みであり、画像分野への応用がどう成立しているかという橋渡しの理解を問う。", "kid": "画像をタイル状に切り分けて、そのタイル1枚1枚を「単語」のように扱う工夫。", "terms": [["CLS token", "分類タスク用に先頭に付け足す特別なトークン。最終的にこのトークンの出力を分類に使う"], ["Position embedding", "パッチの並び順(位置)の情報を加えるための埋め込み"]], "think": "Transformerはもともと単語のような「トークンの並び」を扱う仕組みなので、画像をそのまま入れることはできない。ViTは画像を格子状のパッチに切り分け、それぞれを1つのトークンとみなすことで、Transformerにそのまま入力できる形に変換する。", "vs": "Shifted windowはViTの発展形(Swin Transformerなど)で使われる工夫で、計算範囲を小さな窓に区切りつつ窓の位置をずらして重ね、局所と全体のバランスを取る。", "opt": ["正解。画像を固定サイズのパッチに分割し、各パッチをトークンとして扱いPosition embeddingを加える。", "これはCNNベースの特徴抽出に近い発想であり、ViTが素の画像パッチをそのままトークン化するアプローチとは異なる。", "ViTは色情報(RGB)を含むパッチ単位でトークン化するのが基本形であり、グレースケール化やピクセル単位のトークン化は前提としない。", "周波数領域への変換はViTの標準的な前処理ではなく、パッチへの分割とPosition embeddingが基本形である。"]}'),
  ('e-shikaku-q35', '4. 深層学習の応用', '物体検出のFaster R-CNN(2ステージ検出)とYOLO(1ステージ検出)の違いとして正しいものはどれか。', NULL::text, '["Faster R-CNNは「物体の候補領域を提案する」段階と「その領域のクラスを分類する」段階に分かれているのに対し、YOLOは候補領域の提案と分類を1回のネットワーク通過でまとめて行う。", "Faster R-CNNは1回のネットワーク通過で候補領域の提案と分類をまとめて行い、YOLOはその候補領域の提案とクラス分類をあえて2段階に分けて行うという、それぞれの説明が入れ替わっている。", "Faster R-CNNもYOLOも、どちらも候補領域を提案する処理を一切行わない。", "Faster R-CNNとYOLOは同じアルゴリズムの実装違いにすぎず、速度・精度の傾向に違いはない。"]', 0, '[0]', 'single', '{"asked": "2ステージ検出(Faster R-CNN)と1ステージ検出(YOLO)の処理段階の違い。", "why_asked": "物体検出モデルの「速度と精度のトレードオフ」の背景にある構造の違いを理解しているかを問う定番。", "kid": "Faster R-CNNは「怪しい場所を先に絞ってから、じっくり見る」2段階、YOLOは「画像全体を一気に見て答えを出す」1段階。", "terms": [["Region Proposal Network(RPN)", "物体がありそうな候補領域(Anchor box)を提案するネットワーク"], ["デフォルトボックス", "SSDなどが画像上の各位置にあらかじめ用意しておく、様々な形の候補枠"]], "think": "2段階方式(Faster R-CNN)はRegion Proposal Network(RPN)でまず「物体がありそうな場所」を絞り込んでから、その領域だけを詳しく分類するので精度が出やすいが計算に時間がかかる。1段階方式(YOLO/SSD)は画像全体を一度に処理して候補と分類を同時に出すため高速。", "vs": "FCOSはアンカーフリー(Anchor-Free)方式で、候補枠を事前に用意せず特徴点ごとに直接検出する、さらに別のアプローチ。", "opt": ["正解。Faster R-CNNは候補領域の提案と分類の2段階、YOLOは1回のネットワーク通過でまとめて行う。", "説明が入れ替わっている。2段階に分かれているのはFaster R-CNN、1回で完結するのはYOLOである。", "Faster R-CNNはRegion Proposal Networkで候補領域を明示的に提案する処理を行う点が特徴の1つである。", "2ステージと1ステージでは処理の分かれ方が異なり、一般に精度と速度のトレードオフの傾向も異なる。"]}'),
  ('e-shikaku-q36', '4. 深層学習の応用', '物体検出モデルが同じ物体に対して複数の重なったBounding Boxを出力してしまったとき、最もスコアの高い枠だけを残し、それと大きく重なる他の枠を取り除く後処理はどれか。', NULL::text, '["Non-Maximum Suppression(NMS)。IoU(重なり具合)が一定以上の枠を、スコアが最大のもの以外すべて取り除く。", "ROI Pooling。候補領域ごとに大きさの異なる特徴マップを固定サイズに切り出して揃える処理であり、重複した枠を減らすための後処理ではない。", "ハードネガティブマイニング。学習時に誤りやすい負例を重点的に学習させる工夫であり、推論後の後処理ではない。", "Anchor box。候補枠のテンプレートそのものであり、重複を取り除く処理ではない。"]', 0, '[0]', 'single', '{"asked": "重複したBounding Boxを1つに整理する後処理の名前。", "why_asked": "物体検出モデルはほぼ必ずこの後処理を経て最終的な検出結果を出すため、YOLOやFaster R-CNNと並んでセットで問われる。", "kid": "同じ物体に何個も枠が付いてしまったとき、一番自信のある枠だけを残して他を消す整理整頓の処理。", "terms": [["IoU (Intersection-over-Union)", "2つの枠がどれだけ重なっているかを表す指標。重なり面積÷合計面積"], ["センターネス(Center-ness)", "FCOSで使われる、予測位置が物体の中心にどれだけ近いかを表すスコア"]], "think": "1つの物体に複数の枠が重なって出てくるのはよくあること。NMSは「一番自信のある(スコアが高い)枠」を基準に、それと重なりが大きい(IoUが高い)枠を消していくことで、1物体1枠に整理する。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">NMS：スコア最大の枠だけを残す</text><rect x=\"90\" y=\"35\" width=\"130\" height=\"75\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/><text x=\"95\" y=\"30\" fill=\"#c47070\" font-size=\"9\">0.55</text><rect x=\"110\" y=\"45\" width=\"130\" height=\"75\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/><text x=\"235\" y=\"42\" fill=\"#c47070\" font-size=\"9\">0.62</text><rect x=\"100\" y=\"40\" width=\"130\" height=\"75\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"2.5\"/><text x=\"165\" y=\"132\" fill=\"#6ab08d\" font-size=\"9\" text-anchor=\"middle\">0.91(採用)</text></svg>", "vs": "mAP(mean Average Precision)は検出モデル全体の精度を測る評価指標で、NMSは推論結果を整理する後処理であり、評価の話とは別の場面で登場する。", "opt": ["正解。NMSはスコア最大の枠を基準に、IoUが高い他の枠を取り除いて重複を整理する後処理である。", "ROI Poolingは候補領域の特徴を固定サイズに揃える処理であり、重複した検出結果を整理する処理ではない。", "ハードネガティブマイニングは学習時のデータの選び方の工夫であり、推論後のBounding Boxの整理とは別の場面で使われる。", "Anchor boxは候補枠を生成するためのテンプレートであり、それ自体は重複を取り除く処理を行わない。"]}'),
  ('e-shikaku-q37', '4. 深層学習の応用', 'セマンティックセグメンテーションのU-Netが、ダウンサンプリングで一度小さくした特徴マップを、アップサンプリングする側の同じ解像度の層に橋渡しするために使う仕組みはどれか。', NULL::text, '["スキップコネクション。ダウンサンプリング側の特徴マップを、対応する解像度のアップサンプリング側に直接連結し、細かい位置情報を復元しやすくする。", "Global Average Pooling。各チャネルの特徴マップ全体を平均して1つの値に要約してしまう演算であり、解像度をまたいだ位置情報の橋渡しには使われない。", "ドロップアウト。学習時にニューロンを無効化する正則化であり、解像度の異なる層をつなぐ仕組みではない。", "バッチ正規化。ミニバッチ内で値の分布を整える正規化であり、異なる解像度の層を連結する仕組みではない。"]', 0, '[0]', 'single', '{"asked": "U-Netがダウンサンプリング側とアップサンプリング側の同解像度の層をつなぐ仕組み。", "why_asked": "セグメンテーションは「意味の理解」と「位置の精密さ」を両立する必要があり、U-Netのスキップコネクションがその両立を支える中核の工夫。", "kid": "縮めていく側で見た細かい輪郭の情報を、拡大していく側にこっそり橋渡ししてあげる仕組み。", "terms": [["アップサンプリング", "小さくなった特徴マップを、元の解像度に近づけるように拡大する処理"], ["インスタンスセグメンテーション", "同じクラスの物体でも個体ごとに区別して塗り分ける、さらに細かいセグメンテーション"]], "think": "ダウンサンプリングを繰り返すと画像全体の大まかな意味は捉えやすくなるが、細かい輪郭の位置情報は失われがち。U-Netはダウンサンプリング側の情報をアップサンプリング側にスキップコネクションで直接渡すことで、意味の情報と位置の情報を両方使いながらピクセル単位の分類(セグメンテーション)を行う。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">U-Net：エンコーダとデコーダの橋渡し</text><rect x=\"30\" y=\"30\" width=\"45\" height=\"20\" fill=\"none\" stroke=\"#3b82f6\"/><rect x=\"35\" y=\"55\" width=\"35\" height=\"18\" fill=\"none\" stroke=\"#3b82f6\"/><rect x=\"40\" y=\"78\" width=\"25\" height=\"16\" fill=\"none\" stroke=\"#3b82f6\"/><rect x=\"265\" y=\"30\" width=\"45\" height=\"20\" fill=\"none\" stroke=\"#6ab08d\"/><rect x=\"270\" y=\"55\" width=\"35\" height=\"18\" fill=\"none\" stroke=\"#6ab08d\"/><rect x=\"275\" y=\"78\" width=\"25\" height=\"16\" fill=\"none\" stroke=\"#6ab08d\"/><line x1=\"75\" y1=\"40\" x2=\"265\" y2=\"40\" stroke=\"#c9a04a\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\"/><line x1=\"70\" y1=\"64\" x2=\"270\" y2=\"64\" stroke=\"#c9a04a\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\"/><path d=\"M 52,94 C 52,115 170,115 288,94\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><text x=\"170\" y=\"126\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">同じ解像度同士を横向きに連結(スキップコネクション)</text></svg>", "vs": "ResNetのskip connectionは「同じ解像度のブロック内で入力を足し算する」工夫、U-Netのスキップコネクションは「異なる解像度の層同士を連結する」工夫で、目的も接続の相手も違う。", "opt": ["正解。スキップコネクションでダウンサンプリング側の特徴マップを対応する解像度のアップサンプリング側に連結する。", "Global Average Poolingは特徴マップを1つの値に要約する演算であり、解像度をまたいだ情報の橋渡しには使われない。", "ドロップアウトは正則化の仕組みであり、異なる解像度の層をつなぐ目的の仕組みではない。", "バッチ正規化は値の分布を整える正規化であり、異なる解像度の層を連結する仕組みではない。"]}'),
  ('e-shikaku-q38', '4. 深層学習の応用', 'Word2vecの学習方式であるskip-gramとCBOW(Continuous Bag-of-Words)の違いとして正しいものはどれか。', NULL::text, '["skip-gramは中心となる単語から周囲の単語を予測するのに対し、CBOWは周囲の単語から中心の単語を予測する、予測の向きが逆の関係にある。", "skip-gramは周囲の複数の単語から中心の単語を予測し、CBOWは中心の単語から周囲の単語を予測するという、それぞれの予測方向の説明が入れ替わってしまっている。", "skip-gramとCBOWはどちらも単語の並び順を無視せず、文法規則を明示的にルールとして学習する手法である。", "skip-gramは画像データ専用、CBOWはテキストデータ専用のWord2vec手法である。"]', 0, '[0]', 'single', '{"asked": "Word2vecの2つの学習方式(skip-gram・CBOW)における予測の向きの違い。", "why_asked": "単語埋め込みの古典的な手法として、BERTなどの文脈依存埋め込みと対比するための前提知識になる。", "kid": "skip-gramは「1つの単語から周りを当てる」、CBOWは「周りの単語から真ん中を当てる」、当てっこの向きが逆。", "terms": [["ネガティブサンプリング", "計算量を減らすため、正解の単語以外の一部だけをランダムに選んで学習に使う工夫"], ["n-gram", "連続するn個の単語(や文字)のまとまり。skip gramの「gram」もこの考え方に由来する"]], "think": "Word2vecは「よく同じ文脈に出てくる単語は似た意味を持つ」という考え方で単語をベクトル化する。skip-gramは1つの単語から周りの単語を当てにいき、CBOWは逆に周りの単語をまとめて中心の単語を当てにいく、予測タスクの向きの違いで学習する。", "vs": "潜在的意味インデキシング(LSI)は文書全体の単語出現行列を特異値分解する古典的な手法で、周辺単語からの予測を使うWord2vecとはアプローチが異なる。", "opt": ["正解。skip-gramは中心→周囲、CBOWは周囲→中心という逆向きの予測タスクで単語ベクトルを学習する。", "説明が入れ替わっている。中心から周囲を予測するのがskip-gram、周囲から中心を予測するのがCBOWである。", "skip-gramとCBOWはどちらも周辺単語の共起関係から学習する手法であり、文法規則を明示的なルールとして与えるものではない。", "skip-gramとCBOWはどちらもテキストデータを対象にした学習方式であり、画像専用・テキスト専用という区別ではない。"]}'),
  ('e-shikaku-q39', '4. 深層学習の応用', 'BERTの事前学習で使われるMasked Language Modeling(MLM)というタスクの説明として正しいものはどれか。', NULL::text, '["文中の一部の単語をマスク(隠す)し、周囲の文脈(前後両方)から元の単語を予測させるタスク。", "次に来る単語を、それまでの単語列(前方だけ)を手がかりに予測させる、GPT-nのNext token predictionに近いタスク。", "与えられた2つの文が、文書中で連続しているかどうかを判定させる、Next Sentence Predictionに近いタスク。", "画像とテキストのペアが実際に対応しているかどうかを判定させる、マルチモーダルなモデルで使われるタスク。"]', 0, '[0]', 'single', '{"asked": "BERTの事前学習タスクの1つであるMLMが具体的に何を学習させているか。", "why_asked": "BERT(双方向)とGPT-n(単方向・自己回帰)の違いの根拠になっている、事前学習タスクの設計思想を問う。", "kid": "文中の単語をところどころ隠して、「ここに何が入るでしょう」を前後の文脈から当てさせる穴埋め問題。", "terms": [["事前学習", "大量のテキストで汎用的な言語理解を先に学習しておくフェーズ"], ["ファインチューニング", "事前学習済みモデルを、特定のタスク用のデータで追加学習して調整するフェーズ"]], "think": "BERTは文の前後両方向を見て単語を予測できるように、あえて一部の単語を隠して(マスクして)当てさせる訓練をする。これにより、双方向の文脈を理解した単語の埋め込み(positional embeddings・segment embeddingsなども含む)を事前学習できる。", "vs": "GPT-nは前方向だけの文脈(それまでの単語列)からNext token predictionで次の単語を予測する自己回帰モデルで、BERTの双方向マスク予測とは学習の向きが違う。", "opt": ["正解。MLMは文中の一部をマスクし、前後両方の文脈から元の単語を予測させるタスクである。", "これはGPT-nのNext token predictionの説明であり、前方だけの文脈を使う点がMLM(前後両方を使う)とは異なる。", "これはBERTのもう1つの事前学習タスクであるNext Sentence Predictionの説明であり、MLM(単語の穴埋め)とは別のタスクである。", "画像とテキストの対応判定はマルチモーダルなモデルで使われる考え方であり、MLM(テキスト内の単語の穴埋め)とは異なるタスクである。"]}'),
  ('e-shikaku-q40', '4. 深層学習の応用', 'GPT-nのようなLLMが持つ「Few-shot learning」の特徴として正しいものはどれか。', NULL::text, '["パラメータを追加学習(再学習)せずに、プロンプトの中にいくつかの例を示すだけで、その場でタスクに適応できる能力。", "モデルのパラメータそのものを、少数の追加データを使って改めて再学習(ファインチューニング)することを指す、別の呼び名にすぎない。", "訓練データの中から少数のサンプルだけを使って、最初からモデル全体を学習する手法。", "画像分野のデータ拡張の一種で、少ない画像から新しい訓練画像を生成する手法。"]', 0, '[0]', 'single', '{"asked": "LLMのFew-shot learningが指している具体的な能力。", "why_asked": "Prompt Based LearningやZero-shot learningとセットで、LLM時代特有の「再学習なしでタスクに適応する」パラダイムを理解しているかを問う。", "kid": "重みを1つも変えずに、プロンプトに「お手本」をいくつか見せるだけでコツをつかんでもらう能力。", "terms": [["基盤モデル", "大量のデータで汎用的に事前学習され、様々なタスクの土台として使い回せるモデル"], ["RAG", "外部の文書を検索して回答に反映させることで、LLMが知らない最新情報にも対応させる仕組み"]], "think": "通常の機械学習は新しいタスクごとに再学習が必要だが、大規模言語モデルはPrompt Based Learningの一種として、プロンプトの中に少数の例(Few-shot)や例なし(Zero-shot)でタスクの指示を書くだけで、モデルの重みを変えずにその場で対応できることが多い。", "vs": "Zero-shot learningは例を1つも示さずに指示文だけでタスクに対応させる、Few-shotよりもさらにハードルの高い設定。", "opt": ["正解。Few-shot learningはパラメータを更新せず、プロンプト内の少数の例示だけでタスクに適応する能力を指す。", "ファインチューニングはパラメータそのものを更新する追加学習であり、パラメータを変えないFew-shot learningとは別の仕組みである。", "Few-shot learningは既に学習済みのモデルをその場で使う話であり、モデル全体を最初から学習する手法の説明ではない。", "画像のデータ拡張とは領域が異なり、Few-shot learningはLLMがプロンプト内の例からその場でタスクに適応する能力を指す。"]}'),
  ('e-shikaku-q41', '4. 深層学習の応用', '人の可聴域の上限に近い16kHz(16000Hz)までの音を正しく記録するために必要な、サンプリング定理を満たす最低限のサンプリング周波数はどれか。', NULL::text, '["32kHz。ナイキスト周波数の考え方から、記録したい最大周波数の2倍以上のサンプリング周波数が必要になる。", "16kHz。記録したい最大周波数と同じ値を、2倍することなくそのままサンプリング周波数として使ってしまっている。", "8kHz。記録したい最大周波数を半分にした値を使ってしまっている。", "160kHz。10倍という過剰な安全率を掛けてしまっている。"]', 0, '[0]', 'single', '{"asked": "最大周波数16kHzの音を記録するために必要な最低限のサンプリング周波数。", "why_asked": "音声処理の入口にあるサンプリング定理は、その後のMFCC・WaveNetなどの前提知識になる基本の計算。", "kid": "波の山と谷を最低1回ずつ捉えるには、記録したい一番速い波の2倍の速さで点を打つ必要がある、という話。", "terms": [["サンプリング定理", "元の波形を正しく復元するには、含まれる最大周波数の2倍より高い周波数でサンプリングする必要があるという定理"], ["ナイキスト周波数", "サンプリング周波数の半分の値。この周波数を超える成分は正しく記録できない"]], "think": "波を点(サンプル)で記録するとき、山と谷を最低1回ずつは捉えないと波形を復元できない。1周期あたり最低2点、つまり最大周波数の2倍のサンプリング周波数が必要になる。", "calc": "記録したい最大周波数 : 16,000 Hz\nサンプリング定理 : サンプリング周波数 ≥ 2 × 最大周波数\n2 × 16,000 = 32,000 Hz\n→ 32kHz以上のサンプリング周波数が必要", "vs": "短時間フーリエ変換は「サンプリングした波形」を時間・周波数の両方で見るための変換で、サンプリング定理(そもそも何点で記録するか)とは別の段階の話。", "opt": ["正解。サンプリング定理より、最大周波数16kHzの2倍である32kHz以上が必要になる。", "最大周波数と同じ値でサンプリングすると、波の山と谷を捉えきれず正しく復元できない。", "最大周波数の半分では、波の変化を捉える点の数がさらに不足し、元の波形を復元できない。", "過剰に高いサンプリング周波数は動作するが、サンプリング定理が要求する最低限の値は2倍の32kHzである。"]}'),
  ('e-shikaku-q42', '4. 深層学習の応用', '音声認識の前処理でよく使われるMFCC(メル周波数ケプストラム係数)を作る大まかな流れとして正しいものはどれか。', NULL::text, '["短時間フーリエ変換で周波数成分を求め、人の耳の感度に合わせたメル尺度でスペクトルを圧縮し、さらにケプストラム分析で声道の特徴を抽出する。", "録音した音声波形の生の数値の並びをそのままニューラルネットワークの入力にし、周波数変換もメル尺度への変換もケプストラム分析も一切行わない。", "音声をあらかじめ文字に変換してから、その文字列に出てくる文字の出現頻度をカウントして特徴量にする。", "音声の音量(振幅)の大きさだけを一定間隔でサンプリングし、周波数に関する情報は一切使わずに特徴量にする。"]', 0, '[0]', 'single', '{"asked": "MFCCという音声特徴量を作るまでの大まかな処理の流れ。", "why_asked": "音声処理分野の前処理の定番であり、CTC・WaveNetのようなモデルの入力がどう作られているかの前提知識になる。", "kid": "人間の耳が「低い音の違いには敏感、高い音の違いには鈍感」という性質に合わせて、音の特徴を人間の感覚に近い形に変換していく処理。", "terms": [["メルスペクトログラム", "周波数軸をメル尺度に変換したスペクトログラム(時間×周波数の音の強さの図)"], ["ケプストラム", "スペクトルをさらに変換して、声道の形など「音色」の特徴を取り出す処理"]], "think": "人の耳は低い音の変化には敏感で高い音の変化には鈍感、という性質がある。メル尺度はこの耳の感度に合わせて周波数軸を圧縮する尺度で、そこにケプストラム分析(音の「声色」の特徴を取り出す処理)を組み合わせたのがMFCC。", "vs": "WaveNetは生の波形(または特徴量)から直接、次の音のサンプルを予測して音声合成するモデルで、MFCCのような特徴抽出そのものとは別のタスク(生成)を担う。", "opt": ["正解。短時間フーリエ変換→メル尺度への圧縮→ケプストラム分析という流れでMFCCを作る。", "MFCCはこれらの変換処理を経て作られる特徴量であり、生の波形をそのまま使う場合とは別の前処理である。", "音声認識の前処理は音の波形・周波数情報を扱うものであり、文字への変換や文字の出現頻度のカウントとは異なる処理である。", "MFCCは音量だけでなく周波数の情報(メル尺度・ケプストラム)を積極的に使う特徴量であり、音量だけのサンプリングでは作れない。"]}'),
  ('e-shikaku-q43', '4. 深層学習の応用', '通常のオートエンコーダとVAE(変分オートエンコーダ)の違いとして正しいものはどれか。', NULL::text, '["通常のオートエンコーダは入力を1点の潜在ベクトルに圧縮するのに対し、VAEは潜在変数を確率分布として学習し、そこからサンプリングして新しいデータを生成できるようにしている。", "通常のオートエンコーダは潜在変数を平均・分散を持つ確率分布として学習し、VAEは入力をただ1点のベクトルに圧縮するだけであるという、それぞれの説明が入れ替わってしまっている。", "通常のオートエンコーダもVAEも、どちらも入力データに付随する正解ラベルを人手で用意し、それを教師ありの目的変数として必ず必要とする手法である。", "通常のオートエンコーダとVAEは全く同じ損失関数を使って学習しており、生成できるデータの多様さにも実質的な違いはない。"]', 0, '[0]', 'single', '{"asked": "通常のオートエンコーダとVAEの、潜在空間の扱い方の違い。", "why_asked": "VAEが「生成モデル」として扱われる理由(潜在空間からサンプリングして新しいデータを作れる理由)を理解しているかを問う。", "kid": "普通のオートエンコーダは「1つの正解の点」に圧縮するだけ、VAEは「このあたりに広がっている確率の雲」として圧縮する。", "terms": [["Reparameterization Trick", "確率的なサンプリング処理を、勾配が流れるように「乱数×パラメータ」の形に分離するテクニック"], ["Denoising autoencoder", "入力にわざとノイズを加え、ノイズの無い元のデータを復元させることで、頑健な特徴を学習させる工夫"]], "think": "通常のオートエンコーダは「入力を圧縮して復元できればよい」というだけなので、潜在空間の形は保証されず、ランダムな点から自然なデータを生成するのは苦手。VAEは潜在変数を平均・分散を持つ確率分布として学習し、その分布からサンプリングして生成に使えるようにする(Reparameterization Trickはサンプリングの乱数部分を勾配計算できる形に分離する工夫)。", "vs": "GANは識別器との駆け引きでリアルさを競わせて生成能力を上げる方式で、VAEのように確率分布を明示的に学習する方式とはアプローチが異なる。", "opt": ["正解。VAEは潜在変数を確率分布として学習し、Reparameterization Trickでサンプリングして生成に使えるようにする。", "説明が入れ替わっている。確率分布を学習するのはVAE、1点に圧縮するだけなのは通常のオートエンコーダである。", "通常のオートエンコーダもVAEも、入力データ自体を復元するように学習する教師なし学習であり、ラベルを必須としない。", "通常のオートエンコーダは復元誤差だけを最小化するが、VAEは復元誤差に加えて分布を整えるための項(変分下限に基づく項)も損失に含む点で異なる。"]}'),
  ('e-shikaku-q44', '4. 深層学習の応用', 'GAN(敵対的生成ネットワーク)の学習で、生成器が数種類の似たようなデータばかりを生成するようになり、データの多様性が失われてしまう現象を何と呼ぶか。', NULL::text, '["モード崩壊(mode collapse)。識別器を騙しやすい一部のパターンに生成器が集中してしまい、多様な出力を作らなくなる現象。", "勾配消失。層を重ねすぎたことで逆伝播の勾配が浅い層まで伝わらなくなる現象であり、生成結果の多様性が失われる話とは別の問題である。", "過学習。訓練データの細部までを丸暗記してしまい、新しいデータに対する性能が落ちる現象であり、多様性の欠如そのものを指す専用の語ではない。", "共変量シフト。訓練時とテスト時でデータの分布が変わってしまう現象であり、GAN特有の多様性の問題ではない。"]', 0, '[0]', 'single', '{"asked": "GANの生成結果の多様性が失われてしまう、GAN特有の現象の名前。", "why_asked": "GANの学習が不安定になりやすい理由の代表例であり、Wasserstein GANのような改良版が生まれた背景を理解する土台になる。", "kid": "生成する側が「これさえ出せば審査に通る」というパターンを1つ見つけて、それしか作らなくなってしまう現象。", "terms": [["生成器ネットワーク", "ランダムなノイズから、本物らしいデータを作り出そうとするネットワーク"], ["識別器ネットワーク", "入力されたデータが本物か、生成器が作った偽物かを見分けようとするネットワーク"]], "think": "GANは生成器と識別器が「本物っぽいものを作る側」と「見破る側」に分かれて競い合う。生成器が識別器を騙せるパターンを1つ見つけると、そればかり出力するようになりやすい。これがモード崩壊で、Wasserstein GANなどはこの問題を緩和するために考案された。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">GAN：生成器と識別器の対立</text><rect x=\"40\" y=\"50\" width=\"90\" height=\"40\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"2\"/><text x=\"85\" y=\"74\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">生成器</text><rect x=\"210\" y=\"50\" width=\"90\" height=\"40\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"2\"/><text x=\"255\" y=\"74\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">識別器</text><line x1=\"130\" y1=\"70\" x2=\"210\" y2=\"70\" stroke=\"#60a5fa\" stroke-width=\"2\" marker-end=\"url(#g1)\"/><text x=\"170\" y=\"63\" fill=\"#60a5fa\" font-size=\"8\" text-anchor=\"middle\">偽データ</text><path d=\"M 210,90 C 170,115 130,115 90,90\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\" stroke-dasharray=\"3,2\" marker-end=\"url(#g2)\"/><text x=\"150\" y=\"122\" fill=\"#c9a04a\" font-size=\"8\" text-anchor=\"middle\">見破れたか(フィードバック)</text><defs><marker id=\"g1\" markerWidth=\"7\" markerHeight=\"7\" refX=\"3.5\" refY=\"3.5\" orient=\"auto\"><path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"#60a5fa\"/></marker><marker id=\"g2\" markerWidth=\"7\" markerHeight=\"7\" refX=\"3.5\" refY=\"3.5\" orient=\"auto\"><path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"#c9a04a\"/></marker></defs></svg>", "vs": "条件付きGAN(Conditional GAN)は「このクラスの画像を作って」のような条件を与えて生成を制御する発展形で、モード崩壊とは別の話題(生成のコントロール性)。", "opt": ["正解。識別器を騙しやすい一部のパターンに生成が偏り、多様性が失われる現象をモード崩壊と呼ぶ。", "勾配消失は層を重ねたときの逆伝播の問題であり、GANの生成結果が同じようなものばかりになる多様性の問題とは別の現象である。", "過学習は訓練データへの過剰適合を指す語であり、生成結果の多様性が失われる現象そのものを指す専用の語ではない。", "共変量シフトは訓練時とテスト時のデータ分布のズレを指す語であり、GAN学習中に生成の多様性が失われる現象とは異なる。"]}'),
  ('e-shikaku-q45', '4. 深層学習の応用', 'DQN(Deep Q-Network)が強化学習の学習を安定させるために使う「Experience replay」という工夫の説明として正しいものはどれか。', NULL::text, '["エージェントが経験した(状態・行動・報酬・次の状態)の組を貯めておき、そこからランダムに取り出して学習に使うことで、経験同士の時間的相関を崩して安定させる。", "直前の1回の経験だけを毎回使って、貯めずにその場ですぐパラメータを更新する工夫であり、時間的な相関をむしろ積極的に利用する発想にあたる。", "報酬が得られた成功体験の経験だけをあらかじめ選んで学習に使い、報酬が0だった失敗の経験はメモリーにすら一切残さず、その場ですぐさま完全に捨て去ってしまう工夫。", "他のエージェントが経験したデータを一切共有せず、常にそのとき最新のニューラルネットワークの重みだけを頼りにして次の行動を決めていく工夫。"]', 0, '[0]', 'single', '{"asked": "DQNのExperience replayが学習を安定させるために行っている具体的な工夫。", "why_asked": "深層強化学習の学習が不安定になりやすい理由(データの時間的相関)と、その対処法をセットで理解しているかを問う。", "kid": "経験した出来事をいったんノートに貯めておいて、あとでランダムな順番で復習することで、偏った覚え方をしないようにする工夫。", "terms": [["行動価値関数Q", "ある状態である行動を取ったときに、将来得られる報酬の期待値を表す関数"], ["TD学習", "行動した直後の報酬と、次の状態の価値予測を使って、価値関数を少しずつ更新していく学習方式"]], "think": "強化学習では、直前の行動の結果が次の状態に直接影響するため、経験を発生した順番のまま学習に使うと似たような経験ばかりが連続し、学習が偏りやすい。経験を貯めてランダムに抜き出す(replay)ことで、教師あり学習に近い「独立にサンプリングされたデータ」に近づけて安定させる。", "vs": "A3C(Actor-Critic法)は行動を選ぶ「Actor」と価値を評価する「Critic」を同時に学習する方式で、Q値だけを学習するDQNとはネットワークの構成が異なる。", "opt": ["正解。経験を貯めてランダムサンプリングすることで時間的相関を崩し、学習を安定させるのがExperience replayである。", "直前の1回の経験だけを毎回使う方式は時間的相関が残りやすく、Experience replayが解決しようとしている問題そのものにあたる。", "報酬0の経験も状態遷移の情報として有用であり、Experience replayは報酬の有無で経験を選別する仕組みではない。", "Experience replayは経験の貯め方・使い方の工夫であり、他のエージェントとの経験共有の有無を扱う仕組みではない。"]}'),
  ('e-shikaku-q46', '4. 深層学習の応用', '深層学習の「判断根拠の可視化」に使われるGrad-CAMというテクニックが行っていることの説明として正しいものはどれか。', NULL::text, '["CNNの特定の畳み込み層の勾配情報を使って、画像のどの領域がその予測結果に強く影響したかをヒートマップとして可視化する。", "モデルの重みを完全に別の解釈しやすいモデル(線形モデルなど)に置き換えて、元の予測結果そのものを近似的に再現しようとする。", "訓練データのラベルを付け替えて、モデルが誤分類しやすいデータだけを集める。", "画像を周波数成分に分解し、高周波成分だけを取り除いてノイズを除去する。"]', 0, '[0]', 'single', '{"asked": "Grad-CAMが判断根拠の可視化のために具体的に何を計算しているか。", "why_asked": "深層学習の説明性(XAI)の章で最も代表的な手法であり、LIME・SHAPのような「モデルを近似する」アプローチとの違いを問う。", "kid": "モデルが画像のどこを見てその答えを出したかを、色付きの地図(ヒートマップ)で見せてくれる技術。", "terms": [["XAI (eXplainable AI)", "モデルの判断根拠を人間が理解できる形で示そうとする研究領域全体を指す語"], ["Integrated Gradients", "入力を少しずつ変化させながら勾配を積分していくことで、各入力特徴の寄与度を求める説明手法"]], "think": "Grad-CAMは「最終的な予測に対して、途中の特徴マップの各チャネルがどれだけ寄与したか」を勾配から計算し、それを重みとして特徴マップを重ね合わせることで「モデルが画像のどこを見て判断したか」を色付きの地図(ヒートマップ)として示す。", "vs": "LIME・SHAPは「モデルの近似」によって局所的・大域的な解釈を与えるアプローチで、Grad-CAM・Integrated Gradientsのような「勾配を直接使う」アプローチとは仕組みが異なる。", "opt": ["正解。Grad-CAMは畳み込み層の勾配情報を使って、予測に影響した画像領域をヒートマップとして可視化する。", "これはLIME・SHAPのような「モデルを近似する」アプローチの説明であり、勾配を直接使うGrad-CAMとは仕組みが異なる。", "これは能動学習など別の目的で使われるデータの選び方の話であり、判断根拠の可視化とは異なるテーマである。", "周波数成分の除去は画像処理・ノイズ除去の話であり、モデルの判断根拠を可視化するGrad-CAMの説明ではない。"]}'),
  ('e-shikaku-q47', '5. 開発・運用環境', 'エッジデバイスにモデルを載せるための軽量化手法である「プルーニング」「蒸留(Distillation)」「量子化(Quantization)」の説明の組み合わせとして正しいものはどれか。', NULL::text, '["プルーニングは重要度の低い重みや接続を削る、蒸留は大きな教師モデルの出力を使って小さな生徒モデルを学習させる、量子化はパラメータの数値表現のビット数を減らす手法である。", "プルーニングはパラメータのビット数を減らす、蒸留は重要度の低い重みを削る、量子化は教師モデルから生徒モデルを学習させる手法であるという、説明がすべて入れ替わってしまっている。", "プルーニング・蒸留・量子化はすべて同じ処理を呼び方だけ変えて呼んでいるにすぎず、実装方法にも軽量化の仕組みにも違いはない。", "プルーニング・蒸留・量子化はいずれもモデルの精度そのものを必ず向上させるために使う手法であり、モデルのサイズや計算量には一切影響しない。"]', 0, '[0]', 'single', '{"asked": "モデル軽量化の3手法(プルーニング・蒸留・量子化)それぞれが何をしているか。", "why_asked": "エッジコンピューティングの章の中核であり、3つの手法を混同せずに説明できるかが実務でも問われる。", "kid": "プルーニングは「いらない枝を切る」、蒸留は「先生の知識を生徒に教え込む」、量子化は「数字の細かさを落として軽くする」。", "terms": [["蒸留(Distillation)", "教師モデルのソフトな出力(確信度の分布)を、生徒モデルが真似るように学習させる手法"], ["量子化(Quantization)", "32bit浮動小数点などで持っていたパラメータを、8bit整数のようなより少ないビット数で表現し直す手法"]], "think": "3つとも「性能をできるだけ保ったままモデルを小さく・速くする」という目的は同じだが、アプローチが違う。プルーニングは「不要な枝を切る」、蒸留は「大きなモデルの知識を小さなモデルに教え込む」、量子化は「数値の精度を落として容量と計算量を減らす」というイメージ。", "vs": "これらは「学習済みモデルを軽くする」工夫であり、depth-wise畳み込みを使った「最初から軽いモデル構造」を設計するアプローチとは別軸の話。", "opt": ["正解。プルーニングは重みの削減、蒸留は教師→生徒への知識伝達、量子化はビット数の削減という別々の軽量化手法である。", "説明がすべて入れ替わっており、各手法が本来やっていること(重みを削る・知識を伝える・ビット数を減らす)と対応していない。", "3つの手法は「何を削るか・どう伝えるか」というアプローチが異なる別々の処理であり、同じ処理の別名ではない。", "これらの手法はモデルサイズ・計算量の削減が主目的であり、精度は多くの場合わずかに低下するトレードオフを伴う。"]}'),
  ('e-shikaku-q48', '5. 開発・運用環境', '分散深層学習の「モデル並列化」と「データ並列化」の違いとして正しいものはどれか。', NULL::text, '["モデル並列化は1つの巨大なモデルを複数のデバイスに分割して配置するのに対し、データ並列化は同じモデルのコピーを複数のデバイスに置き、それぞれ異なるミニバッチを処理してから勾配を集約する。", "モデル並列化は複数のデバイスに同じモデルのコピーを置いてデータを分担させ、データ並列化は1つの巨大なモデルを複数デバイスに分割して配置するという、それぞれの説明が入れ替わってしまっている。", "モデル並列化もデータ並列化も、複数のデバイスを使わず1台のデバイス内でのみ行われる工夫である。", "モデル並列化とデータ並列化は同じ処理の別名であり、使い分ける基準は存在しない。"]', 0, '[0]', 'single', '{"asked": "分散深層学習の2つの並列化方式(モデル並列化・データ並列化)の違い。", "why_asked": "巨大なモデルを複数GPUで学習する実務の基本方針であり、どちらを選ぶかはモデルサイズとデータ量のどちらがボトルネックかで決まる。", "kid": "モデル並列化は「1つの大きな仕事を複数人で分担する」、データ並列化は「同じ仕事のコピーを複数人が別々の材料でこなす」。", "terms": [["データ並列化", "同じモデルの複製を複数デバイスに配り、それぞれ違うデータで勾配を計算してから平均する方式"], ["モデル並列化", "1つのモデルの層やパラメータを複数デバイスに分割して配置する方式"]], "think": "1台のGPUのメモリに収まらないほど巨大なモデルは「モデル自体を分割」(モデル並列化)して複数デバイスに置くしかない。モデルは1台に収まるがデータ量が多く学習を速くしたい場合は「モデルのコピーを複数台に置き、データを分担」(データ並列化)して、後で勾配を集約するほうが効率的。", "vs": "連合学習(Federated learning)は、データそのものを1か所に集めずに各デバイス上で学習し、モデルの更新差分だけを集約する点が、データセンター内のデータ並列化とは前提が異なる。", "opt": ["正解。モデル並列化はモデル自体の分割、データ並列化はモデルの複製とデータの分担という異なるアプローチである。", "説明が入れ替わっている。モデルを分割するのがモデル並列化、モデルを複製するのがデータ並列化である。", "これらは複数のデバイス(GPU等)にまたがって処理を分担する、複数デバイス前提の分散学習の手法である。", "モデルサイズがボトルネックか、データ量・学習速度がボトルネックかによって使い分けの基準が存在する。"]}'),
  ('e-shikaku-q49', '5. 開発・運用環境', '連合学習(Federated learning)の特徴として正しいものはどれか。', NULL::text, '["各デバイス(クライアント)上で手元のデータを外に出さずに学習し、パラメータの更新差分だけをサーバーに送ってFederated Averagingなどで集約する。", "各デバイスの手元に散らばっているデータをすべて1か所のサーバーにまとめて集約してから、通常のデータ並列化と全く同じ方式で改めて学習を行う。", "サーバー側だけで一括して集中的に学習を行い、各デバイスはできあがったモデルの推論結果をただ受け取って画面に表示するだけで、学習そのものには一切関与することがない。", "各デバイスがそれぞれ完全に独立したモデルを最初から最後まで学習し、他のデバイスやサーバーとパラメータや更新差分を一切共有しない。"]', 0, '[0]', 'single', '{"asked": "連合学習が「データを1か所に集めずに学習する」ためにどう動いているか。", "why_asked": "プライバシー保護の観点から近年重視される学習方式で、通常の分散学習(データ並列化)との前提の違いを理解しているかを問う。", "kid": "データそのものはスマホの中に置いたまま、「学んだ内容の要約」だけをサーバーに送って、みんなの学びを合体させる仕組み。", "terms": [["クロスデバイス学習", "スマートフォンなど、非常に多数の小さなデバイスを対象にした連合学習"], ["クロスサイロ学習", "病院や企業など、少数だが大きな組織単位を対象にした連合学習"]], "think": "スマートフォンの入力履歴のように、プライバシー上データを外に出したくない場面で使われる。各端末(Local Model)は手元のデータだけで学習し、モデルの重み(または更新差分)だけをサーバーに送る。サーバー側はそれらを集約してGlobal Modelを更新し、また各端末に配る、というサイクルを繰り返す。", "vs": "通常の分散深層学習(データ並列化)はデータセンター内の高速な回線を前提にするのに対し、連合学習は通信が不安定・低速な多数の末端デバイスを前提にする点が大きく異なる。", "opt": ["正解。各デバイス上でデータを外に出さず学習し、更新差分だけをFederated Averagingなどでサーバーが集約する。", "データを1か所に集めてしまうと、連合学習が目的とする「データを外に出さない」という前提が崩れてしまう。", "連合学習は各デバイス側でも学習(Local Model)が行われる点が特徴であり、サーバー側だけで学習が完結するわけではない。", "各デバイスの学習結果(更新差分)はサーバーに送られて集約されるのであって、完全に独立したまま共有しないわけではない。"]}'),
  ('e-shikaku-q50', '5. 開発・運用環境', '深層学習の計算を高速化するデバイスやアーキテクチャの説明として正しいものはどれか。', NULL::text, '["GPUは多数のコアで同じ命令を大量のデータに同時実行するSIMD/SIMT的な設計に強く、行列演算を多用する深層学習と相性が良い。TPUは深層学習向けの専用アクセラレータである。", "GPUは1つの命令を1つのデータに順番に処理する設計に特化した昔ながらの逐次処理向けアーキテクチャであり、行列演算を大量かつ並列に繰り返す深層学習の計算にはそもそも向いていない。", "TPUはGPU本体の計算をさらに高速化するために追加で取り付ける周辺補助機器にすぎず、それ単体では深層学習の計算を何も行うことができない部品である。", "SIMDとMIMDは同じ意味の別名であり、1つの命令で複数のデータを処理するか、複数の命令で複数のデータを処理するかという違いは存在しない。"]', 0, '[0]', 'single', '{"asked": "GPU・TPUがなぜ深層学習の計算に向いているかというアーキテクチャ上の理由。", "why_asked": "「なぜGPUを使うのか」を並列処理の方式(SIMD/SIMT)のレベルで説明できるかを問う、開発・運用環境の基礎知識。", "kid": "GPUは「同じ作業を一気にたくさん同時にこなす」のが得意な作り。行列の掛け算を大量に繰り返す深層学習と相性が良い。", "terms": [["SIMD", "1つの命令で複数のデータに同じ処理を同時に行う方式"], ["MIMD", "複数の命令列が、それぞれ別々のデータに対して並行して処理を行う方式"]], "think": "深層学習の計算(行列積など)は「同じ演算を大量のデータに繰り返す」性質が強く、これはSIMD(単一命令列複数データ)やSIMT(単一命令複数スレッド)の考え方と相性が良い。GPUはもともと画像処理向けにこの並列性を追求した設計で、TPUはさらに深層学習の行列演算に特化して設計された専用チップ。", "vs": "CPUは複雑で多様な命令を柔軟にこなす汎用設計、GPU/TPUは単純な演算を大量に並列実行することに特化した設計、という得意分野の違いを押さえる。", "opt": ["正解。GPUはSIMD/SIMT的な並列設計が行列演算と相性がよく、TPUは深層学習向けに設計された専用アクセラレータである。", "GPUはむしろ同じ命令を大量のデータに同時実行する並列処理に特化しており、深層学習の行列演算と相性が良い設計である。", "TPUはGoogleが開発した、単体で深層学習の計算(特に行列演算)を実行できる専用のアクセラレータチップである。", "SIMDは1つの命令で複数データを処理し、MIMDは複数の命令列がそれぞれ別のデータを処理するという、異なる並列方式である。"]}'),
  ('e-shikaku-q51', '5. 開発・運用環境', '深層学習の環境構築で使われるコンテナ型仮想化(Dockerなど)が、ハイパーバイザー型の仮想化と比べて持つ特徴として正しいものはどれか。', NULL::text, '["ゲストOSを丸ごと持たずホストOSのカーネルを共有するため、起動が速く消費リソースが少ない。その分、ホストOSと異なる種類のOSは動かせない。", "各コンテナがホストとは別の独立したゲストOSをまるごと完全に持つため、ハイパーバイザー型よりもかえって起動が遅く消費リソースがずっと大きくなる。", "コンテナ型はホストOSを一切必要とせず、素のハードウェアの上に直接コンテナを起動して動かすことができる方式である。", "コンテナ型とハイパーバイザー型は仮想化の方式が違うだけで、起動速度も消費リソースも常に同じであり、実用上の違いは存在しない。"]', 0, '[0]', 'single', '{"asked": "コンテナ型仮想化がハイパーバイザー型と比べて軽量である理由と、その代わりに生じる制約。", "why_asked": "深層学習の実験環境をDockerで再現・配布する場面が多く、なぜコンテナが軽いのか、何が制約になるのかを理解しているかが実務で問われる。", "kid": "コンテナ型はホストの土台(カーネル)をそのまま間借りするので身軽、ハイパーバイザー型は毎回OSを丸ごと1つ用意するので重い。", "terms": [["Dockerfile", "コンテナのイメージ(環境の設計図)をどう作るかを記述する定義ファイル"], ["ホスト型仮想化", "ホストOSの上にアプリケーションとして仮想化ソフトを載せる方式。ハイパーバイザー型よりさらにオーバーヘッドが大きい"]], "think": "ハイパーバイザー型(VMware等)はハードウェアの上に複数の「まるごとのOS」を仮想的に立てるので重い。コンテナ型(Docker)はホストOSのカーネルを共有しながらプロセスやファイルシステムだけを隔離するので、起動が速く必要なリソースも少なくて済む。その代わりホストと異なるカーネルのOSはそのままでは動かせない制約もある。", "vs": "深層学習では、GPUドライバやライブラリのバージョン差異による環境構築の手間を、コンテナでまとめて配布・再現できるようにする使われ方が多い。", "opt": ["正解。コンテナ型はホストOSのカーネルを共有するため軽量だが、ホストと異なる種類のOSは動かせない制約がある。", "独立したゲストOSを完全に持つのはハイパーバイザー型の特徴であり、コンテナ型はカーネルを共有することで軽量化している。", "コンテナ型もハイパーバイザー型と同様にホストOSの上で動作する仕組みであり、ホストOSを一切必要としないわけではない。", "ホストOSのカーネルを共有するかどうかという違いにより、起動速度・消費リソースには一般に明確な差が生まれる。"]}'),
  ('e-shikaku-q52', '5. 開発・運用環境', 'スマートフォン上でリアルタイムに動く画像認識アプリを作る場面で、モデルの軽量化手法を選ぶときの考え方として最も適切なものはどれか。', NULL::text, '["推論の速度・消費電力・メモリ制約が厳しいエッジ環境であることを踏まえ、プルーニング・蒸留・量子化を組み合わせ、精度低下を抑えつつモデルを小さく・速くすることを優先する。", "サーバー側のデータセンターで使っているものと全く同じ精度を最優先し、軽量化は一切行わずにそのままの大きさのモデルを端末にまるごと転送して動かす。", "モデルの軽量化についてはそもそも一切考える必要はなく、通信環境をひたすら高速化することだけを考えておけば、エッジ端末側の計算資源やバッテリーの制約は無視してかまわない。", "推論のたびに毎回クラウドのサーバーへ問い合わせて計算させ、端末側では画面表示以外の処理を一切行わない設計にすることを最優先する。"]', 0, '[0]', 'single', '{"asked": "スマートフォンのようなエッジ端末上でモデルを動かすときの軽量化の考え方。", "why_asked": "プルーニング・蒸留・量子化という個々の手法の知識を、実際のエッジコンピューティングの使いどころに接続できるかを問う。", "kid": "スマホは処理能力もバッテリーも限られているから、多少の精度は諦めてでも軽く速く動くモデルを選ぶ判断が必要、という話。", "terms": [["エッジコンピューティング", "クラウドの中心的なサーバーではなく、データが発生する端末や近くの拠点側で計算を行う考え方"]], "think": "エッジコンピューティングは「計算資源が限られる末端デバイス側でその場で処理する」ことが目的なので、通信に頼らずその場で完結できることが利点になる。だからこそモデルの軽量化(プルーニング・蒸留・量子化)が重要になり、精度と速度・省電力のトレードオフを踏まえてどこまで軽くするかを選ぶ判断が実務では問われる。", "vs": "「サーバー側に投げて計算する」構成(クラウド推論)は精度を保ちやすいが通信遅延やオフライン時の弱さがあり、エッジ推論とはトレードオフの関係にある。", "opt": ["正解。エッジ環境の制約を踏まえ、軽量化手法を組み合わせて精度と速度・省電力のバランスを取るのが適切な考え方である。", "軽量化を行わないと、スマートフォンのような限られた計算資源・バッテリーの端末ではリアルタイムに動かすことが難しくなりやすい。", "通信環境だけを高速化しても、端末側で処理する場合の計算資源・メモリ・消費電力の制約そのものは解決しない。", "毎回サーバーに問い合わせる設計は通信遅延やオフライン時に弱く、エッジ側で完結させる利点を活かせない設計である。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'e-shikaku'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
